L28_1 = {}
L28_1.m_CutScenKey_Talk = "ALPHA_ACT1_PLOROGUE1@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3900101
L28_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_SURPRISE"
L28_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "아가씨 괜찮으세요? 식은 땀이 많이 나세요."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "お嬢様、大丈夫ですか？　冷や汗がひどいです。"
L28_1.m_Talk_ENG = "Are you all right? You’re sweating all over."
L28_1.m_Talk_TWN = "小姐，你還好嗎？你流了好多汗。"
L28_1.m_Talk_THA = "เป็นอะไรรึเปล่าคะ? เหงื่อท่วมเลย"
L28_1.m_Talk_VTN = "Cô ổn chứ? Cô ướt hết người rồi."
L28_1.m_Talk_SCN = "小姐你没事吧？怎么出了这么多冷汗。"
L28_1.m_Talk_DEU = "Ist alles okay bei Ihnen? Ihr Schweiß ist eiskalt."
L28_1.m_Talk_FRA = "Tout va bien ? Vous avez des sueurs froides."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "ALPHA_ACT1_PLOROGUE1@29#Talk"
L29_1.m_CutScenProcessKey = 29
