L29_1.m_Talk_FRA = "Jin..."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "ALPHA_ACT1_PLOROGUE1@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 3900101
L30_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L30_1.m_Pos = "C"
L30_1.m_Talk_KOREA = "제가 잠깐 잠들었었군요."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "私、うっかり寝てしまったのですね。"
L30_1.m_Talk_ENG = "...I must’ve fallen asleep."
L30_1.m_Talk_TWN = "我剛不小心睡著了。"
L30_1.m_Talk_THA = "... สงสัยฉันจะหลับไป"
L30_1.m_Talk_VTN = "... Chắc là em ngủ quên mất."
L30_1.m_Talk_SCN = "我好像睡着了。"
L30_1.m_Talk_DEU = "Ich bin kurz eingeschlafen."
L30_1.m_Talk_FRA = "On dirait que je me suis assoupie."
L31_1 = {}
L31_1.m_CutScenKey_Talk = "ALPHA_ACT1_PLOROGUE1@31#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 3900101
L31_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_DESPAIR"
L31_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L31_1.m_Pos = "C"
L31_1.m_Talk_KOREA = "죄송합니다, 아무래도 일정을 좀 무리해서 잡은 것 같군요."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "申し訳ございません、スケジュールに少し無理があったようですね。"
L31_1.m_Talk_ENG = "I’m sorry... It appears that the schedule was a little too ambitious."
L31_1.m_Talk_TWN = "抱歉，都怪我把小姐的行程排得太滿了。"
L31_1.m_Talk_THA = "ขอโทษด้วยค่ะ... ท่าทางว่าตารางจะแน่นไปนะคะ"
L31_1.m_Talk_VTN = "Tôi xin lỗi... Có vẻ như lịch trình như thế này hơi quá."
L31_1.m_Talk_SCN = "抱歉。可能是我日程排得过满了。"
L31_1.m_Talk_DEU = "Entschuldigung, ich habe den Zeitplan wohl etwas zu voll gepackt."
L31_1.m_Talk_FRA = "Le planning j'ai prévu était peut-être trop chargé. Veuillez m'excuser."
L32_1 = {}
L32_1.m_CutScenKey_Talk = "ALPHA_ACT1_PLOROGUE1@32#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 3900101
L32_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L32_1.m_Pos = "C"
L32_1.m_Talk_KOREA = "곧 도착입니다. 내리실 준비를."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "まもなく到着です、降りる準備をいたしましょう。"
L32_1.m_Talk_ENG = "Get ready. We’ll be arriving soon."
L32_1.m_Talk_TWN = "我們就快到了，請準備下飛機。"
L32_1.m_Talk_THA = "เตรียมตัวนะคะ เราจะถึงกันแล้ว"
L32_1.m_Talk_VTN = "Chuẩn bị đi nào. Chúng ta sắp đến nơi rồi."
L32_1.m_Talk_SCN = "马上就要到了，做好降落准备。"
L32_1.m_Talk_DEU = "Wir sind gleich da. Machen Sie sich für den Ausstieg bereit."
L32_1.m_Talk_FRA = "Nous sommes bientôt arrivées. Préparez-vous vos affaires."
