L42_1 = "UNIT_SERIOUS"
L41_1.m_Face = L42_1
L41_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "m_Crash"
L41_1[L42_1] = 10
L42_1 = "아가씨, 정말 괜찮으세요?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "お嬢様、本当に大丈夫ですか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Are you sure you’re okay, Miss Jia?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "小姐，你真的沒事嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "คุณไม่เป็นไรจริงๆ ใช่มั้ยคะคุณเจีย?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cô có chắc là mình ổn không, Tiểu Thư Jia?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "小姐，你真的没事吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Fräulein, geht es Ihnen wirklich gut?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Vous êtes sûre que tout va bien, Mademoiselle ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ALPHA_ACT1_PLOROGUE1@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900101
L42_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_IDLE"
L42_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "네, 괜찮아요. 약간 편두통이 있을 뿐이니까요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ええ、大丈夫です。少し頭痛がするだけですから。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Yes, I’m fine. Just a little headache."
L42_1.m_Talk_ENG = L43_1
L43_1 = "嗯，我沒事，只是有點頭痛而已。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ไม่เป็นไรจริงๆ ค่ะ แค่ปวดหัวนิดๆ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Vâng, em ổn. Chỉ hơi nhức đầu chút thôi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "嗯，我没事。就是有些偏头痛。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ja, alles gut. Habe nur etwas Migräne."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oui, ça va. J'ai juste une migraine."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT1_PLOROGUE1@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3900101
L43_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "UNIT_SERIOUS"
L43_1.m_Face = L44_1
L43_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "힘드시면 지금이라도 돌아갈까요? 무리하면서까지 연회에 참석하실 필요는……."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "もしお疲れなら、今からでも戻りましょうか？\n無理をしてまで宴会に参加する必要は……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Do you want us to turn around? Attending the banquet is not a priority..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不舒服的話，還是我們先回去吧？不需要勉強自己參加宴……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เรากลับกันมั้ยคะ? ยังไงการไปงานเลี้ยงก็ไม่ใช่เรื่องสำคัญอยู่แล้ว"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tiểu thư có muốn chúng ta quay về không? Không cần ưu tiên tham dự bữa tiệc.."
L43_1.m_Talk_VTN = L44_1
L44_1 = "如果身体不舒服，现在就返程吧。没必要勉强自己参加宴会……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wir können jetzt noch zurück, wenn Sie sich nicht wohlfühlen. Sie müssen nicht unbedingt am Bankett teilnehmen ..."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Si vous voulez, nous pouvons toujours rentrer. Inutile de vous surmener pour un simple banquet..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ALPHA_ACT1_PLOROGUE1@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900101
L44_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "UNIT_LAUGH"
L44_1.m_Face = L45_1
L44_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "아뇨. 할아버님께서 가르쳐주셨거든요. 가족끼리는 사이 좋게 지내야 한다고."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "いいえ、お祖父様はこうおっしゃいました。家族は仲良くあるべきだって。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "No. Grandfather taught me that I should get along with family."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不行，我爺爺有說，家人之間要相親相愛。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ไม่ได้ค่ะ คุณปู่สอนว่าฉันควรญาติดีกับครอบครัว"
L44_1.m_Talk_THA = L45_1
L45_1 = "Không. Ông đã dạy em rằng nên hòa thuận với gia đình."
L44_1.m_Talk_VTN = L45_1
L45_1 = "不。爷爷曾经教导我，家人之间要和睦相处。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Geht schon. Großvater sagte stets, dass sich Familienmitglieder gut vertragen müssen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ça ira. Mon grand-père m'a toujours dit qu'il fallait garder de bonnes relations avec les membres de la famille."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
