L49_1 = "ALPHA_ACT1_PLOROGUE1@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3900101
L48_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_IDLE"
L48_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L49_1 = "R"
L48_1.m_Pos = L49_1
L49_1 = "오늘은 일 년에 한 번뿐인 혁신의 밤이잖아요? 다른 가족분들이 기다리고 계실 거예요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "今日は年に一度の革新の夕べですから。\n家族の皆さんがお待ちになっていると思います。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Tonight is the annual The Night of Innovation. Everyone else is will be waiting for us."
L48_1.m_Talk_ENG = L49_1
L49_1 = "今天是一年一度的革新之夜，大家一定都在等我們。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "คืนนี้เป็นงานราตรีประจำปีของอินโนเวชั่นนะคะ ทุกคนกำลังรอเราอยู่"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đêm nay là Đêm Cải Cách mỗi năm chỉ có một lần. Những người khác đều sẽ chờ chúng ta."
L48_1.m_Talk_VTN = L49_1
L49_1 = "今天是一年一度的“革新之夜”不是吗？还有其他家人们在等我。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Es ist doch eine revolutionäre Nacht, die nur einmal im Jahr stattfindet! Die anderen Familienmitglieder warten bestimmt schon."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Aujourd'hui c'est la Nuit de l'innovation, un évènement qui ne se déroule qu'une fois par an. Toute la famille doit être en train de m'attendre."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "ALPHA_ACT1_PLOROGUE1@49#Talk"
