L51_1 = "R"
L50_1.m_Pos = L51_1
L51_1 = "다른 맴버 분들은 모두 도착하셨나요?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "他のメンバーのみなさんは全員到着されていますか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Have the other members arrived already?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "其他人都到了嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "สมาชิกคนอื่นๆ มาถึงรึยังคะ?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Các thành viên khác đã đến chưa?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "别的成员们都到了吗？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Sind die anderen Mitglieder schon angekommen?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Les autres sont déjà arrivés ?"
