L1_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L2_1 = "L"
L1_1.m_Pos = L2_1
L2_1 = "네. 아가씨께서 주무시고 계실 때, 초원 양에게 연락받았습니다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "はい、お嬢様がお休みになっている間に、\nナオさんから到着の連絡を受けました。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Yes. While you were sleeping, Chowon reported in."
L1_1.m_Talk_ENG = L2_1
L2_1 = "都到了，剛剛小姐睡著的時候，我有接到初源的通知。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "มาแล้วค่ะ โชวอนรายงานมาตอนที่คุณหลับอยู่"
L1_1.m_Talk_THA = L2_1
L2_1 = "Rồi. Trong khi cô đang ngủ, Chowon đã tới."
L1_1.m_Talk_VTN = L2_1
L2_1 = "是的。小姐睡着的时候，接到了桃沢梨绘的通讯报告。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ja. Als Sie geschlafen haben, hat mich Chowon benachrichtigt."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Oui, Chowon m'a contactée pendant que vous dormiez."
L1_1.m_Talk_FRA = L2_1
