L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3900101
L3_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_DESPAIR"
L3_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L4_1 = "R"
L3_1.m_Pos = L4_1
L4_1 = "아쉬워라……. 저도 멤버 분들이랑 같이 지하철이라는 걸 꼭 타 보고 싶었는데."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "残念だわ……私もメンバーのみなさんと一緒に、地下鉄というモノに乗ってみたかったのに。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "It’s a shame... I wanted to ride the thing called the \"subway\" with everyone."
L3_1.m_Talk_ENG = L4_1
L4_1 = "真可惜……好想跟大家一起搭搭看地鐵喔。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "น่าเสียดายจัง... ฉันอยากนั่งที่เขาเรียก “รถไฟใต้ดิน” มากับทุกคนแท้ๆ เลยนะคะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Thật tiếc... Em đã muốn đi thứ gọi là \"tàu điện ngầm\" với mọi người."
L3_1.m_Talk_VTN = L4_1
L4_1 = "好可惜……我原本也想和其他队员们一起乘坐那个叫地铁的东西。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wie schade ... Ich wollte auch mit den anderen Mitgliedern mit diesem Ding namens Bahn fahren."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Quel dommage... J'aurais tellement aimé prendre le métro avec les autres."
L3_1.m_Talk_FRA = L4_1
