L7_1[1] = L8_1
L7_1[2] = L9_1
L5_1[L6_1] = L7_1
L6_1 = "돌아갈 때는 꼭 다 같이 타고 가요. 이진 언니."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "帰りは絶対にみんなで乗りましょう、ホノカさん。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Let’s ride it back home with the others, Jin."
L5_1.m_Talk_ENG = L6_1
L6_1 = "李珍姐，我們回程的時候就一起搭地鐵吧？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เดี๋ยวเรานั่งกลับบ้านกับคนอื่นกันเถอะค่ะจิน"
L5_1.m_Talk_THA = L6_1
L6_1 = "Mình đi tàu về nhà với những người khác Jin nhé."
L5_1.m_Talk_VTN = L6_1
L6_1 = "回去的时候，一起坐地铁吧。李珍姐姐。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Lass uns auf der Rückreise zusammen die Bahn nehmen, Jin."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Jin, vous voulez bien qu'on rentre en métro tous ensemble après la soirée ?"
L5_1.m_Talk_FRA = L6_1
