L7_1 = "ALPHA_ACT1_PLOROGUE1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3900101
L6_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L6_1.m_bWaitClick = true
