L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "……아쉽게도 그건 좀 어려울 것 같군요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "……残念ですが、それはちょっと難しいかと。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "...I’m afraid that might be difficult."
L6_1.m_Talk_ENG = L7_1
L7_1 = "……很抱歉，可能沒辦法。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "...เกรงว่าจะยากนะคะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "... Tôi e rằng điều đó có thể hơi khó."
L6_1.m_Talk_VTN = L7_1
L7_1 = "……抱歉，我可能没办法和你们一起坐地铁了。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "... Ich befürchte, dass es schwierig wird."
L6_1.m_Talk_DEU = L7_1
L7_1 = "... Je suis navrée, mais ça va être difficile."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
