L7_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "연회가 끝나고 부회장님께서 따로 호출하셔서요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "宴会の後は、副会長に呼び出されていますので。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "The Vice Chairman wants to see me after the banquet is over."
L7_1.m_Talk_ENG = L8_1
L8_1 = "宴會結束後，副會長另外有事找我。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "รองประธานเรียกฉันไปพบหลังงานเลี้ยงค่ะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Phó Chủ Tịch muốn gặp tôi sau khi bữa tiệc kết thúc."
L7_1.m_Talk_VTN = L8_1
L8_1 = "副会长想要在宴会结束后单独约见我。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich wurde vom Herrn Vizepräsidenten gebeten, ihn nach dem Bankett zu treffen."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Le vice-président m'a demandé de lui rendre visite après le banquet."
L7_1.m_Talk_FRA = L8_1
