L11_1 = "아하, 이진 언니는 이노베이션에 오기 전에는 숙부님의 비서셨죠?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "残念ですね。そういえば、ホノカさんはイノベーションに来る前、叔父様の秘書をされていましたよね？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "That’s right! You were Uncle’s secretary before joining Innovation."
L10_1.m_Talk_ENG = L11_1
L11_1 = "哦～李珍姐之前是叔叔的秘書對吧？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "จริงด้วย! คุณเป็นเลขาฯ คุณลุงก่อนมาทำงานกับอินโนเวชั่นนี่นา"
L10_1.m_Talk_THA = L11_1
L11_1 = "Đúng rồi! Chị là thư ký của Bác trước khi tham gia Cải Cách Alphatrix."
L10_1.m_Talk_VTN = L11_1
L11_1 = "啊哈，我差点就忘了，李珍姐姐来阿尔法崔克斯改革之前是叔父的秘书呢~"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Aha, du warst doch Onkels Sekretärin, bevor du zur Innovation gewechselt bist, oder?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Aha, je vois. Vous étiez la secrétaire de mon oncle auparavant n'est-ce pas ?"
L10_1.m_Talk_FRA = L11_1
