L13_1 = "ALPHA_ACT1_PLOROGUE1@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3900101
L12_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_SURPRISE"
L12_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "……네. 이젠 아니지만요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.05
L13_1 = "はい。今はもう違いますが……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Yes... But not anymore."
L12_1.m_Talk_ENG = L13_1
L13_1 = "……是的，但現在不是。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ค่ะ... แต่ก็ไม่ได้เป็นแล้ว"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ừ... Nhưng không còn như vậy nữa."
L12_1.m_Talk_VTN = L13_1
L13_1 = "……是的。但现在已经不是了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "... Ja. Damals."
L12_1.m_Talk_DEU = L13_1
L13_1 = "... Oui. Mais ce n'est plus d'actualité."
L12_1.m_Talk_FRA = L13_1
