L14_1 = "ALPHA_ACT1_PLOROGUE1@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900101
L13_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "UNIT_PRIDE"
L13_1.m_Face = L14_1
L13_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "그렇구나. 오랫동안 못 보셨으니까 비서 시절 생각이 많이 나시겠네요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そうでしたね。叔父様とは久しぶりに会いますし、\n色々と秘書時代のことを思い出すひと時になりそうですね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I see. Then I’m sure you were delighted to see him again."
L13_1.m_Talk_ENG = L14_1
L14_1 = "那你們這麼久不見，應該會想起很多以前的事吧～"
L13_1.m_Talk_TWN = L14_1
L14_1 = "งั้นฉันว่าคุณคงดีใจที่ได้เจอท่านอีกแน่เลย"
L13_1.m_Talk_THA = L14_1
L14_1 = "Em hiểu rồi. Vậy thì em chắc là chị sẽ rất vui khi gặp lại bác ấy."
L13_1.m_Talk_VTN = L14_1
L14_1 = "这样啊。这么久没见，你们应该有很多想聊的事情吧。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ach so. Du vermisst sicherlich die Zeit als Sekretärin, da es ja schon eine Weile her ist."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je vois. Ça doit vous rappeler le temps où vous travaillez pour lui, non ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
