L16_1.m_Face = "UNIT_IDLE"
L16_1.m_StartBGMFileName = "CUTSCENE_AMBIENT_WIND"
L16_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "할아버님께서 가르쳐 주셨죠. 오래된 인연일수록 소중히 여겨야만 한다고요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "お祖父様に教わったのです。古くからの縁ほど、大切にすべきだと。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Grandfather always taught me that the older the relationship, the more important it is to cherish it."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我爺爺有說，認識得越久，越要好好珍惜這段關係。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คุณปู่สอนเราเสมอเลยนะคะว่า มิตรภาพยิ่งยาวนานยิ่งควรถนอมรักษาไว้อย่างยิ่ง"
L16_1.m_Talk_THA = L17_1
L17_1 = "Ông luôn dạy chúng em rằng mối quan hệ càng lâu thì ta càng phải trân trọng."
L16_1.m_Talk_VTN = L17_1
L17_1 = "爷爷曾经说过，时间越久的缘分，就越要珍惜。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Großvater sagte stets, dass man seine Kontakte pflegen sollte."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mon grand-père m'a toujours dit qu'il fallait accorder de l'importance aux relations qu'on entretient depuis longtemps."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "ALPHA_ACT1_PLOROGUE1@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3900101
L17_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_LAUGH"
L17_1.m_Face = L18_1
L17_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "저희는 신경 쓰지 말고, 숙부님과 천천히 이야기 나누고 오세요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "私たちのことは気にせず、叔父様とゆっくりなさってくださいね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Don’t worry about us, and enjoy your time with Uncle."
L17_1.m_Talk_ENG = L18_1
L18_1 = "你不用擔心我們，就跟叔叔好好敘舊吧～"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ไม่ต้องห่วงเรานะคะ ไปหาคุณลุงให้มีความสุขเถอะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Đừng lo về tụi em, hãy dành thời gian với Bác em đi nhé."
L17_1.m_Talk_VTN = L18_1
L18_1 = "不用担心我们，李珍姐姐你就和叔父慢慢聊吧~"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Rede ruhig mit meinem Onkel und mach dir um uns keine Gedanken."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ne nous vous en faites pas pour nous et allez discuter avec votre oncle."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
