L23_1[L24_1] = L25_1
L24_1 = "역시 알파트릭스 임직원들이 전부 모이는 회식 자리다워……! 클래스가 달라!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "アルファトリックスの全社員が集う懇親会場はやっぱり違うね……！\n別次元だよ！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "So this is what a banquet with all of the Alphatrix employees looks like...! It’s on another level!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "真不愧是阿爾法崔克斯所有職員一起參與的聚餐……！等級完全不一樣！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "งานเลี้ยงที่มีพนักงานของอัลฟาทริกซ์พร้อมหน้าเป็นแบบนี้เองนะคะเนี่ย...! คนละชั้นกันเลย!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Vậy là bữa tiệc có tất cả nhân viên Alphatrix sẽ trông như thế này đây ...! Nó hoàn toàn ở một đẳng cấp khác!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "不愧是阿尔法崔克斯全体职员们聚餐的地点……！真是奢华！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Das ist wahrhaftig eine Jahresfeier der Führungskräfte von Alphatrix ...! Einfach grandios!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Les soirées d'Alphatrix sont vraiment d'un autre niveau... !"
L23_1.m_Talk_FRA = L24_1
