L27_1 = "m_Crash"
L26_1[L27_1] = 20
L27_1 = "좋아! 아침부터 쫄쫄 굶은 보람이 있어!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "よし！　朝からお腹を空かせた甲斐があるな！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Okay, then! It was worthwhile not to eat anything today!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "非常好！不枉費我從早上餓到現在！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แบบนี้ละก็! ที่หิ้วท้องรอมาทั้งวันก็คุ้มแล้วล่ะ!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tuyệt! Thật xứng đáng khi cả ngày nay không ăn gì!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "太棒了！我从早上开始就饿着肚子，这次要大吃一顿！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Gut! Es hat sich gelohnt, den ganzen Morgen zu hungern!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "J'ai bien fait d'avoir gardé le ventre vide, héhé !"
L26_1.m_Talk_FRA = L27_1
