L31_1 = "UNIT_SERIOUS"
L30_1.m_Face = L31_1
L31_1 = "SEAROM_ALPHA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "L_M_I"
L30_1.m_Pos = L31_1
L31_1 = "가브리엘! 너 지금 뭐하는 거야?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ガブリエル！　何してるの？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Gabriel! What are you doing?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "加布里埃爾！你在幹嘛？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "กาเบรียล! ทำอะไรของนายน่ะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Gabriel! Đang làm gì đấy?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "加尔！你在干嘛？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Gabriel! Was machst du da?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Gabriel ! Qu'est-ce que tu fais ?"
L30_1.m_Talk_FRA = L31_1
