L32_1 = "ALPHA_ACT1_PLOROGUE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3900101
L31_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "CHOI_ALPHA_NULL_SHORT"
L31_1.m_CharStrID = L32_1
L32_1 = "R"
L31_1.m_Pos = L32_1
L32_1 = "보면 모르는가, 소녀여. 음식을 포장하는 중이다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "見てわからないのか、少女よ。食べ物を調達しているのだ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Can’t you see, girl? I’m packing food."
L31_1.m_Talk_ENG = L32_1
L32_1 = "這位少女，你看不出來嗎？我在打包啊。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไม่มีตาหรือแม่นาง? ข้าก็ห่ออาหารกลับไงล่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Cô không thấy sao, cô gái? Tôi đang gói thức ăn."
L31_1.m_Talk_VTN = L32_1
L32_1 = "还用问吗，少女。当然是在打包食物啦。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Siehst du nicht, Mädchen? Ich packe etwas vom Essen ein."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tu ne vois pas ? J'emballe de la nourriture."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "ALPHA_ACT1_PLOROGUE1@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3900101
L32_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "CHOI_ALPHA_NULL_SHORT"
L32_1.m_CharStrID = L33_1
L33_1 = "R"
L32_1.m_Pos = L33_1
L33_1 = "내일과 모레, 그리고 글피의 일용할 양식을 위해서."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "明日と明後日、そして明々後日のためにな。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It’s food that I’ll eat tomorrow, the day after, and the next!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "這些是我明天、後天和大後天要吃的。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อาหารที่ข้าจะกินพรุ่งนี้ มะรืน แล้วก็วันถัดไปด้วย!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đó là thức ăn mà tôi sẽ ăn vào ngày mai, ngày kia và ngày hôm sau nữa!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "我要打包走明天、后天、还有大后天要吃的东西！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das ist für Morgen und Übermorgen und Überübermorgen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Pour demain, après-demain, et les jours suivants."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ALPHA_ACT1_PLOROGUE1@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3900101
L33_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "SEAROM_ALPHA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "L"
L33_1.m_Pos = L34_1
L34_1 = "m_Crash"
L33_1[L34_1] = 30
L34_1 = "아니, 바보야! 남들 다 보는데 부끄럽지도 않아?!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "バカ！　みんなが見てるのに恥ずかしくないわけ！？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Hey! Don’t you feel embarrassed doing that with everyone here?!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你傻啦！大家都在看，不覺得丟臉嗎？！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "นี่! ไม่อายบ้างเหรอนั่น คนเต็มไปหมดเลยนะ?!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Này! Cậu không cảm thấy xấu hổ khi làm điều đó trong khi mọi người đều ở đây sao?!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "喂，你这个蠢货！别人都在看呢，不觉得丢脸吗？！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ach Dummerchen! Schämst du dich denn nicht vor den anderen?!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Quel idiot ! Non mais tu n'as pas honte ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "ALPHA_ACT1_PLOROGUE1@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3900101
L34_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_PRIDE"
L34_1.m_Face = L35_1
L35_1 = "CHOI_ALPHA_NULL_SHORT"
L34_1.m_CharStrID = L35_1
L35_1 = "R"
L34_1.m_Pos = L35_1
L35_1 = "m_Crash"
L34_1[L35_1] = 10
L35_1 = "훗. 어리석은 건 그대다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "フッ、愚かなのは君だ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Pfft! You are the foolish ones."
L34_1.m_Talk_ENG = L35_1
L35_1 = "呵，傻的是你。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เฮอะ! เจ้านี่ก็โง่เสียจริง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Xì! Đồ ngốc."
L34_1.m_Talk_VTN = L35_1
L35_1 = "哈，你才是愚蠢的那一个。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hah. Das Dummerchen bist du."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ha ha. Je pense que c'est plutôt toi l'idiote."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "ALPHA_ACT1_PLOROGUE1@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3900101
L35_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "CHOI_ALPHA_NULL_SHORT"
L35_1.m_CharStrID = L36_1
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "그렇게 다람쥐 도토리 감추듯 양 볼 가득 욱여넣어도 인간의 위장엔 한계가 존재하지."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "そうやってリスみたいにぎゅうぎゅうほっぺに詰めたところで、\n人間の胃袋には限度がある。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Even if you try stuffing your face like a squirrel, the human stomach can only hold so much."
L35_1.m_Talk_ENG = L36_1
L36_1 = "就算我們可以像倉鼠一樣，把食物藏在兩頰裡，但是能藏的數量畢竟有限的！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ต่อให้คุณทำหน้าเหมือนกระรอก กระเพาะมนุษย์ก็ยัดได้ไม่มากนักหรอก"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ngay cả khi cô vùi đầu vào ăn như một con sóc, dạ dày của con người cũng chỉ có thể chứa được bấy nhiêu thôi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "就算你像仓鼠一样把嘴巴塞得鼓鼓囊囊，但作为人类，你的胃容量也是有限的。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Es bringt nichts, sich das Maul voll zu stopfen, denn der menschliche Magen hat schließlich seine Grenzen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tu auras beau remplir te remplir la panse comme un écureuil, l'estomac humain a ses limites."
L35_1.m_Talk_FRA = L36_1
