L38_1 = "UNIT_PRIDE"
L37_1.m_Face = L38_1
L38_1 = "FX_CUTSCEN_TADA"
L37_1.m_StartFXSoundName = L38_1
L38_1 = "CHOI_ALPHA_NULL_SHORT"
L37_1.m_CharStrID = L38_1
