L40_1 = 2
L41_1 = 0.15
L39_1[1] = L40_1
L39_1[2] = L41_1
L37_1[L38_1] = L39_1
L38_1 = "그래서는 행복감의 <color=#ffd34c>균형</color>을 맞출 수가 없어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そんなことでは、幸福感の<color=#ffd34c>バランス</color>がとれない。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "With that, the <color=#ffd34c>balance</color> of happiness can’t be met."
L37_1.m_Talk_ENG = L38_1
L38_1 = "這樣是無法達到幸福感的<color=#ffd34c>平衡</color>的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เพราะอย่างนั้น <color=#ffd34c>สมดุล</color>แห่งความสุขน่ะไม่มีจริงหรอก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Thế thì, cô không thể đạt tới <color=#ffd34c>sự cân bằng</color> của hạnh phúc đâu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这样可不能维持幸福感的<color=#ffd34c>均衡</color>。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "So kann man <color=#ffd34c>das Gleichgewicht</color> des Glücks nicht erreichen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ce n'est pas comme ça que tu trouveras l'<color=#ffd34c>équilibre</color> du bonheur."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT1_PLOROGUE1@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900101
L38_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "UNIT_SERIOUS"
L38_1.m_Face = L39_1
L39_1 = "SEAROM_ALPHA_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "m_Crash"
L38_1[L39_1] = 20
L39_1 = "균형의 문제가 아니라 매너의 문제겠지!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "バランスじゃなくてマナーの問題でしょ！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It’s not about balance, it’s a matter of having manners!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "現在又不是在說平衡的事，是禮貌的問題！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "มันเรื่อง “สมดุล” ที่ไหนล่ะ นี่มันเรื่องมารยาท!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vấn đề không phải là về \"sự cân bằng\", mà là cách ứng xử!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "这不是均衡的问题，而是礼仪的问题！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Das ist kein Problem des Gleichgewichts, sondern der Manieren!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ce n'est pas un problème d'équilibre, c'est simplement une question de manières !"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ALPHA_ACT1_PLOROGUE1@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900101
L39_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "SEAROM_ALPHA_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "이런 곳에서 음식 싸가는 게 민폐라는 자각은 있는 거야?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "こんな場所で食べ物の持ち帰りだなんて、\nマナー違反だってことはわかってるの？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Don’t you know how rude it is to pack food from places like this?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "你這樣打包會影響到別人吃的權利啦！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไม่รู้เหรอว่าห่ออาหารในที่แบบนี้กลับบ้านน่ะหยาบคายขนาดไหน?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cậu không biết việc gói đồ ăn mang về từ những nơi như thế này thật bất lịch sự sao?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "在这样的场合打包食物，你有没有想过会给人添麻烦？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ist dir überhaupt bewusst, dass das Mitnehmen von Essen auf solchen Feiern unhöflich für andere ist?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Tu ne sais pas que c'est malpoli d'emporter de la nourriture dans un lieu pareil ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "ALPHA_ACT1_PLOROGUE1@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3900101
L40_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_HATE"
L40_1.m_Face = L41_1
L41_1 = "CHOI_ALPHA_NULL_SHORT"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "어차피 남으면 버릴 것 아닌가?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "どうせ余ったら捨てるんだろう？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "But it’s all going to be thrown away, no?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "吃剩的不也是丟掉嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ยังไงก็เหลือทิ้งอยู่แล้วไม่ใช่เหรอ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nhưng nếu không ăn thì chúng sẽ bị vứt hết, không phải sao?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "反正吃不掉的不也得扔掉吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Die Reste werden doch eh weggeschmissen, oder?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "De toute façon les restes vont finir à la poubelle, non ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "ALPHA_ACT1_PLOROGUE1@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3900101
