L42_1 = "CHOI_ALPHA_NULL_SHORT"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "m_Crash"
L41_1[L42_1] = 20
L42_1 = "내 행실이 그렇게 마음에 안 들면 실력으로 막아 봐라, 소녀여."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "私の行動がそんなに気に食わないなら、実力で阻止するがいい。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Girl, if you think my actions are that bad, then try to stop me."
L41_1.m_Talk_ENG = L42_1
L42_1 = "你對我的行為有意見的話，有本事就來阻止我啊，少女！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "นี่ แม่นาง ถ้าที่ข้าทำมันแย่นัก ก็ลองมาหยุดดูสิ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cô gái à, nếu cô nghĩ hành động của tôi tệ đến vậy, thì hãy cố gắng ngăn tôi lại đi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "如果你看不惯，不如用你的实力阻止我吧，少女。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wenn dir mein Verhalten nicht gefällt, dann halt mich doch auf, Mädchen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Si mon comportement te déplaît tant, essaie de m'en empêcher, jeune fille."
L41_1.m_Talk_FRA = L42_1
