L46_1 = "UNIT_SERIOUS"
L45_1.m_Face = L46_1
L46_1 = "SEAROM_ALPHA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "L"
L45_1.m_Pos = L46_1
L46_1 = "큭……! 드디어 본색을 드러내는군, 괴인 싹쓰러가!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "くっ……！　ついに本性を現したわね、この大食い怪人！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Grr...! So now you show your true intentions, you monster scum!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "可惡……！終於原形畢露了吧！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "หนอย...! เผยธาตุแท้แล้วสินะ ไอ้คนสารเลวนี่!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Grr ...! Vậy là bây giờ cậu định lộ rõ ý định của mình phải không, đồ quái vật cặn bã!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "啊哈……！你终于露出本来面目了吗，你这个怪物！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ngh ...! Jetzt zeigst du dein wahres Gesicht, du Monster!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Rah... ! Tu montres enfin ton véritable visage, sale monstre !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
