L47_1 = "m_Crash"
L46_1[L47_1] = 20
L47_1 = "가면 카운터를 본받은 자로서, 너의 악행은 용서할 수 없다!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "仮面カウンターに追随する者として、あなたの悪態は許せないわ！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "As I follow in the footsteps of the Masked Counter, your misdeeds cannot be forgiven!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "身為蒙面制裁者的代言人，我絕不能原諒你的惡行！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ในเมื่อฉันตามรอยเท้าของหน้ากากเคาน์เตอร์ การกระทำอันชั่วร้ายของแกนี่ก็ให้อภัยไม่ได้แล้ว!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Từ khi tôi đi theo Counter Giấu Mặt, những hành vi sai trái của cậu là không thể tha thứ được!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "作为假面制裁者的接班人，我不会饶恕你的恶行！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Als jemand, der den Lehren des Maskierten Counters folgt, kann ich dir deine Missetat nicht verzeihen!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "En tant qu'héritière spirituelle du Counter Masqué, je ne peux pas te laisser faire !"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
