L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3900101
L7_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L7_1.m_bWaitClick = true
