L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "지금 연회장 한복판에서 칼자루에 손을 가져다 댄 것 같은데……"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "今、宴会場のど真ん中で刀の柄に手をかけたように見えましたが……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I could’ve sworn I saw the two of you getting ready to fight in the middle of this banquet..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "現在是要在大庭廣眾之下亮刀嗎……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "สาบานได้เลยว่าฉันเห็นเธอสองคนตีกันกลางงานเลี้ยงนี่..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Chị có thể thề rằng chị đã thấy hai đứa sẵn sàng đánh nhau ngay giữa bữa tiệc này..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "刚刚我好像看到你要在宴会现场拔刀……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Mitten in der Festhalle ein Messer in der Hand?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je me trompe, ou vous étiez à deux doigts de dégainer vos épées en plein banquet... ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "ALPHA_ACT1_PLOROGUE1@108#Talk"
