L8_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L8_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "제가 잘못 본 게 맞겠죠?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私の見間違いですよね？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "But it’s all my imagination, right?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "應該是我眼花吧？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แต่ฉันคงคิดไปเองแหละ ใช่มั้ย?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Nhưng là do chị tưởng tượng thôi nhỉ?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "应该是我看错了吧，你说对不对？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich habe mich bestimmt verguckt, richtig?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je me fais des idées, j'espère..."
L8_1.m_Talk_FRA = L9_1
