L11_1[L12_1] = 15
L12_1 = "그, 그건 피치 못할 사정으로……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "こ、これはやむを得ず……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Th-there’s been a misunderstanding..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那個…我也是逼不得已……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "มะ-มันเป็นเรื่องเข้าใจผิดน่ะ..."
L11_1.m_Talk_THA = L12_1
L12_1 = "H-hiểu lầm thôi mà..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "那、那是因为有不得已的……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "D-das war ein unausweichlich ..."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Non mais... Je n'ai pas eu le choix..."
L11_1.m_Talk_FRA = L12_1
