L14_1 = "UNIT_SERIOUS"
L13_1.m_Face = L14_1
L14_1 = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL"
L13_1.m_StartFXSoundName = L14_1
L13_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "분명 신신당부했을 텐데요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "あれほど念を押したはずです。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I told you all to behave tonight, didn’t I?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "我不是交代過你們嗎？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันบอกแล้วใช่มั้ยนะว่าคืนนี้ให้ทำตัวเรียบร้อยกันนะ?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Chị đã nói tất cả phải cư xử cho phải phép tối nay phải không?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "我早就说过吧。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich habe doch darum gebeten."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Vous avez déjà oublié les consignes ?"
L13_1.m_Talk_FRA = L14_1
