L15_1 = "ALPHA_ACT1_PLOROGUE1@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900101
L14_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL"
L14_1.m_StartFXSoundName = L15_1
L14_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "오늘은 1년에 단 한 번, 알파트릭스 전 임직원이 모이는 혁신의 밤."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "今日は年に一度、アルファトリックスの全社員が集まる革新の夕べ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "The Night of Innovation is the one day of the year that all employees of Alphatrix gather together."
L14_1.m_Talk_ENG = L15_1
L15_1 = "今天是阿爾法崔克斯全集團一年一度的革新之夜。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "งานราตรีประจำปีของอินโนเวชั่นเป็นวันเดียว\nในหนึ่งปี ที่พนักงานทุกคนของอัลฟาทริกซ์จะได้มาพร้อมหน้ากัน"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đêm Cải Cách là ngày duy nhất trong năm mà tất cả nhân viên của Alphatrix tề tựu."
L14_1.m_Talk_VTN = L15_1
L15_1 = "今天是一年仅有一次的，阿尔法崔克斯全体职员们的聚餐之夜。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Es ist eine revolutionäre Nacht, in der nur einmal im Jahr alle Führungskräfte von Alphatrix zusammenkommen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "La Nuit de l'innovation est une occasion unique qui rassemble tout le personnel d'Alphatrix."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
