L15_1[L16_1] = L17_1
L16_1 = "m_CharScaleTime"
L17_1 = 0.1
L15_1[L16_1] = L17_1
L16_1 = "부디 오늘만큼은 이노베이션의 이름에 먹칠하는 일이 없길 바란다고."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "どうか今日だけはイノベーションの名前に\n泥を塗るようなことをしないようにと言ったはずですが。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Please do your best not to make a mockery of Innovation tonight."
L15_1.m_Talk_ENG = L16_1
L16_1 = "今天絕對不能丟公司的臉！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ขอร้องหล่ะ ช่วยอย่าทำอะไรให้อินโนเวชั่นต้องอายเลยนะคืนนี้"
L15_1.m_Talk_THA = L16_1
L16_1 = "Hãy cố gắng hết sức để không khiến sự kiện Cải Cách tối nay trở thành trò cười đấy."
L15_1.m_Talk_VTN = L16_1
L16_1 = "希望今天你们不要给阿尔法崔克斯改革的招牌丢脸。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Besonders heute darf nichts passieren, das dem Ruf der Innovation schadet."
L15_1.m_Talk_DEU = L16_1
L16_1 = "S'il y a bien quelque chose qu'on ne peut pas se permettre, et encore moins aujourd'hui, c'est de salir le nom d'Innovation !"
L15_1.m_Talk_FRA = L16_1
