L20_1 = "m_Crash"
L19_1[L20_1] = 20
L20_1 = "저흰 그냥 서로한테 어울리는 디저트를 추천해주고 있었거든요!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私たちはお互い好きそうなデザートを勧めていただけですから！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "We were actually recommending each other desserts!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "我們剛只是在推薦對方好吃的甜點啦！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "จริงๆ เรากำลังชวนกันกินของหวานอยู่นะคะ!"
L19_1.m_Talk_THA = L20_1
L20_1 = "Thực ra bọn em đang giới thiệu các món tráng miệng cho nhau!"
L19_1.m_Talk_VTN = L20_1
L20_1 = "刚才我们只是在互相推荐对方适合吃的甜点而已！"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wir haben uns nur gegenseitig passende Desserts empfohlen!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Nous essayions juste de trouver des desserts qui nous correspondraient mieux !"
L19_1.m_Talk_FRA = L20_1
