L22_1.m_CharStrID = L23_1
L23_1 = "L"
L22_1.m_Pos = L23_1
L23_1 = "어라!? 이런 곳에 푸석푸석해 보이는 머핀이!?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "あれ！？　こんな所にパサパサなマフィンが！？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Ooh! Look at that muffin that looks so dry!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "哇！？看起來好蓬鬆的瑪芬喔！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "โห! ดูมัฟฟินนั่นสิ แห้งดีจัง!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Ôi! Trông cái bánh xốp khô quá!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "哎呀！？这些松饼看起来真的又松又软耶！？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wie?! Ein trocken aussehender Muffin auf einer solchen Feier?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Tiens ! Regardez ce muffin tout sec !"
L22_1.m_Talk_FRA = L23_1
