L28_1 = "C_F_R"
L27_1.m_Pos = L28_1
L28_1 = "엇!? 때마침 여기 소녀를 닮은 곰보 빵이……!?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あれぇ！？　ちょうどこんなところに、とってもカチカチなメロンパンが……！？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Huh?! This streusel bread looks like you, girl!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "喔？！這麼巧！這裡有和少女你長得一樣的芝麻麵包欸……？！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "หือ?! ขนมปังกรอบนี่หน้าตาเหมือนเจ้าเลยนะ!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ấy?! Bánh mì streusel này trông hệt như cô ấy, cô gái!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "咦！？这块奶油面包长得好像你唉，少女……！？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Was?! Apropos, hier ist ein Streuselkuchen, der so aussieht wie du, Mädchen!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Tiens regarde, ce pain soboro est ton portrait craché !"
