L31_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "m_Crash"
L31_1[L32_1] = 15
L32_1 = "후훗, 오늘도 두 분은 사이가 좋으시네요. 다행이에요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "フフッ、今日もお二人は仲良しですね。ほほえましいです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Ho ho. I see you two are having fun."
L31_1.m_Talk_ENG = L32_1
L32_1 = "呵呵，你們感情還是這麼好，真好～"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โฮะโฮะ พวกคุณสองคนดูสนุกกันดีนะคะ..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Ho ho. Tôi thấy hai người đang rất vui vẻ."
L31_1.m_Talk_VTN = L32_1
L32_1 = "嘻嘻，看来今天你们两个非常和睦呢，太好了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Haha, sie vertragen sich mal wieder gut heute. Was ein Glück."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ha ha. Je suis ravi de voir que vous vous entendez toujours aussi bien."
L31_1.m_Talk_FRA = L32_1
