L34_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "……김 비서. 저 사람들은 뭐죠?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "……秘書よ、あの者たちはいったい何ですか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Mr. Kim, who are they?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "……金秘書，那些人是誰？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คุณคิม พวกนั้นใครน่ะ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Thư ký Kim, họ là ai?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "……金秘书。她们是谁？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "... Sekretär Kim. Wer sind diese Leute?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "... Monsieur Kim. Qui sont ces gens ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "ALPHA_ACT1_PLOROGUE1@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3900101
L34_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "고져스해야 하는 자리에 누가 저런 버릇없는 꼬맹이들을 데려왔답니까?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ゴージャスでなければならないこの会場に、\n誰があんな躾のなっていない子どもたちを連れてきたのでしょう？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "What are ill-mannered children doing at a sophisticated event like this?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "這裡這麼有水準，是誰把沒水準的小鬼帶來的？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เด็กมารยาททรามพวกนั้นมาทำอะไรในงานเลี้ยงหรูหรานี่กัน?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Bọn nhóc thô lỗ ấy đang làm gì ở một sự kiện tinh tế như thế này?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "在这么高雅的场合，是谁带那两个不懂规矩的小不点来的？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wer hat diese kleinen Frechdachse zu einem so wunderschönen Ort mitgeschleppt?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Qui a fait venir ces gamins à notre respectable soirée ?"
L34_1.m_Talk_FRA = L35_1
