L37_1 = "ALPHA_ACT1_PLOROGUE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3900101
L36_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "SECRETARY_NPC_ALPHA_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "귀국하신 지 얼마 안 되셔서 국내 사정은 잘 모르시는군요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "帰国されたばかりで、まだご存じなかったのですね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Allow me to fill you in on the details of what happened while you were out of the country."
L36_1.m_Talk_ENG = L37_1
L37_1 = "因為您才剛回國沒多久而有所不知。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ขอผมอธิบายรายละเอียดให้ฟังนะครับว่าเกิดอะไรขึ้นบ้าง ตอนคุณที่อยู่ต่างประเทศ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cho phép tôi nói rõ về những điều đã xảy ra trong khi ngài ở nước ngoài."
L36_1.m_Talk_VTN = L37_1
L37_1 = "因为回国没多久，所以您可能还不了解国内的情况。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Sie sind noch nicht so lange zu Lande, sodass Sie mit den Umständen hier noch nicht so vertraut sind."
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est vrai que vous êtes rentré depuis peu. Vous n'êtes surement pas au courant des dernières nouvelles."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ALPHA_ACT1_PLOROGUE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900101
L37_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "SECRETARY_NPC_ALPHA_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "그룹의 프로모션용으로 설립했던 태스크포스입니다. 내부에서 꽤 유명하죠."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "グループプロモーションの一環として設立されたタスクフォースカンパニーです。\n内部ではかなり有名ですよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "They are part of the Group’s promotional Task Force. They are quite well-known within the company."
L37_1.m_Talk_ENG = L38_1
L38_1 = "他們是專門用來替集團打廣告的特遣勢力，在集團裡的名氣滿大的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "พวกเขาอยู่ในทาสก์ฟอร์ซด้านส่งเสริมการขายของกลุ่มครับ ค่อนข้างมีชื่อในบริษัทเลยทีเดียว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Họ là một phần của Lực Lượng Đặc Nhiệm quảng bá của Tập Đoàn. Họ khá nổi tiếng trong công ty."
L37_1.m_Talk_VTN = L38_1
L38_1 = "她们是为宣传集团形象而创建的一个特遣势力。在集团内非常出名。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das ist die TASKFORCE, die für die Förderung unserer Gruppe gegründet wurde. Sie ist innerbetrieblich sehr bekannt."
L37_1.m_Talk_DEU = L38_1
L38_1 = "C'est une nouvelle TASKFORCE créée pour promouvoir le groupe. Ils sont plutôt connus en interne."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT1_PLOROGUE1@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900101
L38_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "아아, 그 얼굴 모를 최대 주주께서 제안하셨다던 언터처블 프로모션 팀?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ああ、あの匿名の筆頭株主が提案したという\nアンタッチャブル・プロモーションチームのことですか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Aah... The promotional team that the unknown biggest shareholder had suggested?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "喔～你說那個神祕的大股東提議的不受管制行銷小組嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อ้อ ทีมส่งเสริมการขายที่ผู้ถือหุ้นใหญ่ลึกลับแนะนำมานะเหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Aah ... Nhóm quảng bá mà một cổ đông lớn giấu tên đã đề xuất sao?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "啊啊，是那位没露过面的最大股东提议组建的宣传团队？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ah, das Promotion-Team, das der unbekannte Großaktionär vorgeschlagen hat?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ah ! Cette équipe de promotion UNTOUCHABLE proposée par le plus grand actionnaire de l'entreprise, que personne n'a jamais vu ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ALPHA_ACT1_PLOROGUE1@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900101
L39_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "무슨 짓을 해도 내부에서 아무 간섭 못 한다는 그……?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "何をしても、内部からは一切干渉できないという噂の……？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "So that’s the division that gets away with anything...?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "集團完全不能干涉他們的任何行動……？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "พวกนั้นก็เลยลอยนวลไปได้เรื่อยๆสินะ...?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Vậy ra đây là nhóm sẵn sàng làm bất cứ công việc gì đấy à...?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "听说不管她们惹出多大麻烦，集团内部都不能干涉……？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Sie meinen das Team, dem keiner im Betrieb etwas entgegensetzen kann ...?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Celui dont personne ne connaît les agissements en interne..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3900101
L40_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L40_1.m_bWaitClick = false
L40_1.m_fWaitTime = 1
L41_1 = {}
L42_1 = "ALPHA_ACT1_PLOROGUE1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3900101
L41_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "SECRETARY_NPC_ALPHA_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "사실은 좀 다릅니다. 윗분들 방침은 간섭하지 않는 게 아니라, 방치하는 거죠."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "実情は若干異なります。上層部の方針は干渉しないのではなく、\n放置することになっています。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Not quite like that. The higher-ups' policy is to leave them alone rather than intervene."
L41_1.m_Talk_ENG = L42_1
L42_1 = "其實有點出入，上面的想法是放任他們自取滅亡，而不是不干涉。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ก็ไม่เชิงแบบนั้นครับ แต่จะยังไง นโยบายของเบื้องบนก็คืออย่าไปวุ่นวายมากกว่าเข้าไปแทรกแซง"
L41_1.m_Talk_THA = L42_1
L42_1 = "Không hẳn là như vậy. Tuy nhiên, chính sách của cấp trên là để họ yên chứ không can thiệp."
L41_1.m_Talk_VTN = L42_1
L42_1 = "事实与传闻还是有区别的。比起干涉，其实大多高层都是持放养的态度。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Aber eigentlich es ganz anders. Die Führungskräfte mischen sich nicht bewusst nicht ein, sondern vernachlässigen einfach ihre Pflicht."
L41_1.m_Talk_DEU = L42_1
L42_1 = "En réalité, ce n'est pas que les gens en haut ne souhaitent pas s'en mêler. C'est surtout qu'ils laissent couler."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ALPHA_ACT1_PLOROGUE1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900101
L42_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "SECRETARY_NPC_ALPHA_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "작전 중에 실패해서 객사하길 바라면서요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "作戦中に失敗して勝手に死んでくれることを願いながら。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "They do hope that some will die during their operations."
L42_1.m_Talk_ENG = L43_1
L43_1 = "希望他們直接在作戰時因公殉職。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถึงอย่างนั้น เราก็หวังว่าบางคนจะตายๆ ไปซะตอนปฏิบัติภารกิจนะครับ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tuy nhiên, cũng có hy vọng rằng vài người trong nhóm sẽ chết trong khi tác chiến."
L42_1.m_Talk_VTN = L43_1
L43_1 = "大概是希望她们在执行作战时客死他乡吧。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Im Wunschdenken, dass sie während der Mission einfach umkommen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ils espèrent que sa stratégie échoue et qu'il périsse au cours d'une mission."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT1_PLOROGUE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3900101
L43_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "……객사? 대체 그게 무슨 말이죠?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "……勝手に死ぬ？　それはどういう意味でしょう？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "...Die? What do you mean?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "……因公殉職？這什麼意思？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "...ตายเหรอ? หมายความว่ายังไงน่ะ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "...Chết? Ý anh là sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "……客死他乡？为什么这么说？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "... Umkommen? Was meinen Sie?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "... Qu'il périsse au cours d'une mission ? Je ne comprends pas."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ALPHA_ACT1_PLOROGUE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900101
L44_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "다이브마다 코스트도 꽤 될 텐데, 실패하길 바란다고요?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ダイブにかかるコストも相当なはずなのに、失敗を望んでいると？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Each dive is costly, and yet they want them to fail?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "每次躍入要花那麼多錢，卻希望他們戰敗？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ไดฟ์แต่ละทีแพงมากนะ พวกนั้นยังอยากให้ล้มเหลวอีกเหรอ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Mỗi lần lặn rất đắt đỏ, vậy mà họ lại muốn mấy người này thất bại?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "每次跃入的出击费用应该很高吧，为什么会希望她们作战失败呢？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Die Kosten eines Tauchgangs sind doch extrem hoch und dennoch wollen sie, dass sie scheitern?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ils veulent qu'il échoue ? Alors que les Plongées nous coûtent aussi cher ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ALPHA_ACT1_PLOROGUE1@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900101
L45_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "SECRETARY_NPC_ALPHA_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "……대표님도 신씨 일가의 사정은 한 번쯤 들어 보셨을 텐데요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "……代表もヒメノ家の事情について、一度は耳に入れたことがあるかと。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I’m sure you’ve heard the rumors of the Shin family, have you not?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "……您應該也聽說過沈氏家族的事。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ผมว่าคุณน่าจะได้ยินข่าวลือของตระกูลเฉินมาบ้างแล้วไม่ใช่เหรอครับ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi chắc là ngài đã nghe tin đồn về gia đình Shin, phải không ạ?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "……您也听说过沈氏家族的传闻吧。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "... Sie haben sicherlich auch schon einmal von den Umständen der Familie Shin gehört."
L45_1.m_Talk_DEU = L46_1
L46_1 = "... Vous devriez vous intéresser davantage aux histoires de la famille Shin."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "ALPHA_ACT1_PLOROGUE1@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3900101
L46_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "SECRETARY_NPC_ALPHA_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "돌아가신 회장님이 애지중지하던 <color=#ffd34c>손녀</color>에 대한 이야기를요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "亡くなった会長が溺愛していた<color=#ffd34c>孫娘</color>についてです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "About the late President’s <color=#ffd34c>granddaughter</color> that he so treasured."
L46_1.m_Talk_ENG = L47_1
L47_1 = "就是過世的會長最疼愛的<color=#ffd34c>孫女</color>的事。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เรื่อง<color=#ffd34c>หลานสาว</color>หัวแก้วหัวแหวนของประธานคนล่าสุดน่ะครับ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Về <color=#ffd34c>cháu gái</color> của cố Chủ Tịch mà ông ấy rất yêu quý."
L46_1.m_Talk_VTN = L47_1
L47_1 = "关于已故会长大人最喜爱的<color=#ffd34c>孙女</color>的那些传闻。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Die Geschichte der <color=#ffd34c>Enkeltochter</color>, die der verstorbene Vorsitzende so geliebt hat."
L46_1.m_Talk_DEU = L47_1
L47_1 = "En essayant d'en savoir plus sur la petite fille préférée du défunt directeur."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "ALPHA_ACT1_PLOROGUE1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3900101
L47_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ELECTRONICSCEO_NPC_ALPHA_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "뭐? 그럼 혹시 그……?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "えっ？　じゃあ、まさかあの……？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "What? Then what you’re saying is...?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "什麼？難道是……？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "หา?... งั้นตายที่ว่าก็คือ...?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Sao? Vậy anh đang nói tới...?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "什么？难道是……？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Was? Könnte es sein, dass ...?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Quoi ? Vous voulez dire que... ?"
L47_1.m_Talk_FRA = L48_1
