L4_1 = "ALPHA_ACT1_PLOROGUE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3900101
L3_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_IDLE"
L3_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L4_1 = "R_M_I"
L3_1.m_Pos = L4_1
L4_1 = "여기 계셨군요, 한참 찾았어요. 초원 씨."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "こちらにいらしたのですね。ずいぶん探しましたよ、ナオさん。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "There you are. I’ve been looking all over for you, Ms. Chowon."
L3_1.m_Talk_ENG = L4_1
L4_1 = "初源，我找了你好久，原來你在這裡。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อยู่นี่เอง ฉันตามหาไปทั่วเลยค่ะคุณโชวอน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cậu đây rồi. Tôi đã tìm cậu khắp nơi đấy Chowon."
L3_1.m_Talk_VTN = L4_1
L4_1 = "你在这里啊，找了你好久呢。梨绘。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Hier sind Sie ja. Ich habe Sie schon eine Weile gesucht, Chowon."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vous voilà, Chowon ! Je vous cherchais partout."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "ALPHA_ACT1_PLOROGUE1@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3900101
L4_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "UNIT_PRIDE"
L4_1.m_Face = L5_1
L4_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "같이 케이크 먹으러 가요. 다들 기다리고 계세요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "一緒にケーキを食べに行きましょう。皆さんもナオさんのことを待っていますよ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Let’s go have some cake. Everyone’s waiting."
L4_1.m_Talk_ENG = L5_1
L5_1 = "一起去吃蛋糕吧，大家都在等你呢。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ไปทานเค้กกันเถอะค่ะ ทุกคนรออยู่"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đi ăn bánh ngọt nào. Mọi người đang chờ đấy."
L4_1.m_Talk_VTN = L5_1
L5_1 = "一起去吃蛋糕吧。大家都在等着呢。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Lassen Sie uns zusammen Kuchen essen gehen. Alle warten schon."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Allons mangez un morceau de gâteau. Tout le monde vous attend."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "ALPHA_ACT1_PLOROGUE1@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3900101
L5_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "CHOWON_ALPHA_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "L"
L5_1.m_Pos = L6_1
L6_1 = "아뇨, 리더. 저는 여기서 좀 쉬고 있겠습니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "いいえ、リーダー。私はここで少し休みます。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "No thank you, Leader. I’ll stay here and rest."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不了，老大。我想在這裡休息一下。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่ล่ะค่ะท่านผู้นำ ฉันอยู่เงียบๆ ตรงนี้ดีกว่า"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không, cảm ơn Thủ Lĩnh. Tôi sẽ ở lại đây và nghỉ ngơi."
L5_1.m_Talk_VTN = L6_1
L6_1 = "不了，队长。我想在这里休息一会。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Nein, ich bleibe hier und ruhe mich ein wenig aus."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Non ça ira chef, je vais me reposer ici."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "ALPHA_ACT1_PLOROGUE1@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3900101
L6_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_LAUGH"
L6_1.m_Face = L7_1
L7_1 = "CHOWON_ALPHA_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "L"
L6_1.m_Pos = L7_1
L7_1 = "다들 저희 팀을 주목하고 계셔서 몸 둘 바를 모르던 참이었거든요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "みんなが私たちのチームに注目していて、\nどうすれば良いのかわからなくなっていたところです。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "All eyes are on our team, so I’m stumped on what to do."
L6_1.m_Talk_ENG = L7_1
L7_1 = "大家好像一直在討論我們的事，我覺得有點不自在。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ใครๆ ก็มองทีมของเราจนฉันทำอะไรไม่ถูกเลย"
L6_1.m_Talk_THA = L7_1
L7_1 = "Mọi con mắt đều đổ dồn vào nhóm của chúng ta, vậy nên tôi chẳng biết phải làm gì nữa."
L6_1.m_Talk_VTN = L7_1
L7_1 = "我们队伍好像受到了很多人的关注，这让我有些……紧张呢。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wegen der Aufmerksamkeit, die auf unser Team gerichtet ist, wusste ich nicht, wie ich darauf reagieren sollte."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tout le monde avait les yeux rivés sur notre équipe alors je cherchais un endroit où me cacher."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
