L9_1 = "ALPHA_ACT1_PLOROGUE1@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3900101
L8_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_IDLE"
L8_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "……흐음. 그렇군요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "……ふむ、そうなのですね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "...Hmm. As you wish, then."
L8_1.m_Talk_ENG = L9_1
L9_1 = "……嗯嗯，原來是這樣。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "...อืมมม ตามใจนะคะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "... Hmm. Vậy thì như ý cậu muốn vậy."
L8_1.m_Talk_VTN = L9_1
L9_1 = "……嗯，原来是这样。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "... Hm. Verstehe."
L8_1.m_Talk_DEU = L9_1
L9_1 = "... Je vois."
L8_1.m_Talk_FRA = L9_1
