L10_1 = "ALPHA_ACT1_PLOROGUE1@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3900101
L9_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "UNIT_PRIDE"
L9_1.m_Face = L10_1
L9_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "그럼, 제가 같이 있어 드릴게요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "でしたら、私もご一緒します。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Then, I’ll stay here with you."
L9_1.m_Talk_ENG = L10_1
L10_1 = "那我一起在這裡陪你。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "งั้นฉันอยู่ด้วยแล้วกัน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi sẽ ở đây với cậu."
L9_1.m_Talk_VTN = L10_1
L10_1 = "那，我陪你一会吧。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Dann bleibe ich bei Ihnen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Dans ce cas, je vais rester avec vous."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "ALPHA_ACT1_PLOROGUE1@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3900101
L10_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SURPRISE"
L11_1 = "CHOWON_ALPHA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "네? 아뇨, 일부러 그러실 필요까진……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "え？　いえ、そこまでして頂く必要は……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Huh? N-no, you don’t need to..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "什麼？不用啦，你不需要這樣……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "หา? มะ-ไม่เอาสิ ไม่ต้องหรอก..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Huh? K-không, cô không cần..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "啊？不，不用特意这样……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Was? Nein, Sie müssen nicht ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Pardon ? Vous n'êtes pas obligée..."
L10_1.m_Talk_FRA = L11_1
