L14_1 = "ALPHA_ACT1_PLOROGUE1@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900101
L13_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "UNIT_PRIDE"
L13_1.m_Face = L14_1
L13_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "할아버님께서 그러셨거든요. 항상 직원분들을 가족처럼 생각하는 사람이 되라고요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "お祖父様はこうおっしゃいました。\n常に社員の皆さんを家族のように気遣える人になりなさいって。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Grandfather said that we need to treat our employees like family."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我爺爺有說，要我把員工當家人一般看待。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "คุณปู่เคยบอกค่ะว่าเราต้องเห็นพนักงานเป็นเหมือนคนในครอบครัว"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ông nội thường nói rằng chúng ta cần phải đối xử với nhân viên của mình như gia đình."
L13_1.m_Talk_VTN = L14_1
L14_1 = "爷爷曾经说过。要将职员们当作家人一样对待。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Großvater hat einst gesagt, dass man seine Mitarbeiter wie seine eigene Familie behandeln sollte."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mon grand-père me disait toujours de traiter le personnel de l'entreprise comme ma famille."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
