L18_1 = {}
L19_1 = "ALPHA_ACT1_PLOROGUE1@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900101
L18_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "이야, 직원은 가족처럼 생각하면서 정작 진짜 가족에게는 얼굴도 안 비추는구나?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "おいおい、社員は家族のように気遣うのに、\n本当の家族のところには顔も出さないのか？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Would you look at that. You treat your employees like family, but never come and show your face to your real ones?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "哎呀～說什麼把員工當作家人，結果對真正的家人卻是避而不見？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ฟังพูดเข้า เธอเห็นพนักงานเป็นคนในครอบครัว แต่ไม่เคยโผล่มาให้คนในครอบครัวจริงๆ เห็นหน้าเลยเนี่ยนะ?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ai da. Em đối xử với nhân viên của mình như gia đình, nhưng không bao giờ dám thể hiện con người thật sự trước mặt họ sao?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "哎呀呀，将职员当作家人一样对待，但对真正的家人却不管不顾呢？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "So so, die Mitarbeiter wie die Familie behandeln, aber nicht einmal bei der eigentlichen Familie vorbeischauen?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Et ta vraie famille alors ? Tu ne prends même pas la peine de leur donner des nouvelles ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "ALPHA_ACT1_PLOROGUE1@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3900101
L19_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "그래도 한때는 사업 파트너였는데 좀 섭섭한데."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "これでも一時はビジネスパートナーだったのに、少し寂しいな。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I mean, we were business partners once, right?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "虧我們還曾經是事業上的夥伴，真是傷我的心～"
L19_1.m_Talk_TWN = L20_1
L20_1 = "คือ เราทำธุรกิจด้วยกันอยู่ไม่ใช่เหรอ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ý anh là, chúng ta đã từng là đối tác kinh doanh, phải không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "好歹我们也是曾经的商业合作伙伴，我有些失望啊。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Als ehemalige Geschäftspartner finde ich das sehr schade."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Nous avons été partenaires, pourtant..."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
