L23_1 = "ALPHA_ACT1_PLOROGUE1@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3900101
L22_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_IDLE"
L22_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "안 그래도 찾아뵈려 했는데, 죄송해요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ちょうどご挨拶に伺おうと思っていたところです。申し訳ありません。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I’m sorry. I was just on my way to see you all."
L22_1.m_Talk_ENG = L23_1
L23_1 = "對不起，我正打算你找你的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ขอโทษค่ะ ฉันกำลังจะไปหาทุกคนเลย"
L22_1.m_Talk_THA = L23_1
L23_1 = "Em xin lỗi. Em đang định đi gặp tất cả mọi người đây."
L22_1.m_Talk_VTN = L23_1
L23_1 = "原本想一会去找你来着，抱歉。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich hatte vor, dich zu besuchen. Tut mir leid."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Justement, je comptais aller vous saluer. Mais vous avez été plus rapide."
L22_1.m_Talk_FRA = L23_1
