L25_1 = "ALPHA_ACT1_PLOROGUE1@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3900101
L24_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "하하. 아냐, 아냐. 신경 쓰지 마. 지금이라도 봤으면 됐지, 뭘."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ハハハ。いやいや、気にするな。こうやって会えたんだからいいんだよ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Hah hah. I got to see you now, so no worries."
L24_1.m_Talk_ENG = L25_1
L25_1 = "哈哈～沒事沒事，別緊張，現在見到面就好啦～呵～"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฮ่าฮ่า ผมมาเจอเองแล้วไง ไม่ต้องกังวลหรอก"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ha ha. Giờ anh đã gặp được em rồi, không sao."
L24_1.m_Talk_VTN = L25_1
L25_1 = "哈哈哈。开玩笑的。我现在来见你也是一样的。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Haha. Keine Ursache. Wir sehen uns ja jetzt."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Ha ha. Ne t'inquiète pas. L'essentiel, c'est que nous nous sommes retrouvés."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "ALPHA_ACT1_PLOROGUE1@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3900101
L25_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "그보다 지아야. 괜찮은 비지니스가 있는데 어때? 한 번 들어 볼래?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "それよりユイ。良いビジネスチャンスがあるんだが、どうだ？　一度聞いてみないか？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Anyway, Jia? I’ve got an interesting business proposition, if you care to listen?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "不過我想跟你談個生意，你要聽聽看嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ว่าแต่ว่านะเจีย ผมมีข้อเสนอทางธุรกิจที่น่าสนใจอยู่ล่ะ อยากลองฟังดูมั้ย?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Dù sao thì, Jia? Anh có một đề xuất kinh doanh thú vị, em có muốn nghe không?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "话说，小佳。我有一个非常不错的商业项目，你想了解一下吗？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Davon abgesehen, habe ich ein Geschäftsanliegen, Jia. Bist du interessiert?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Au fait, j'ai une affaire intéressante à te proposer. Tu voudrais bien m'écouter ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
