L28_1 = "UNIT_PRIDE"
L27_1.m_Face = L28_1
L27_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "아하. 헤비암즈 건은 정말 유감이에요, 오라버니."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "そうでしたね！　ヘビーアームズの件は本当に残念でした、お兄様。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Oh, I’m truly sorry for what happened at Heavyarms."
L27_1.m_Talk_ENG = L28_1
L28_1 = "喔～重武裝的事我也覺得很遺憾，大哥。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อ๋อ เรื่องฝ่ายอาวุธหนักฉันเสียใจด้วยจริงๆ นะคะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ôi, em thực sự rất tiếc vì những gì đã xảy ra tại Heavyarms."
L27_1.m_Talk_VTN = L28_1
L28_1 = "啊！重武装军工那件事真的很抱歉，哥哥。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Aha. Der „Heavy Arms“-Fall ist sehr bedauerlich, Jaehyuk."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ah. Je suis navrée pour ce qui s'est passé pour Heavyarms."
L27_1.m_Talk_FRA = L28_1
