L29_1 = "如果现在需要我的帮助……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wenn du meine Hilfe benötigst ..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Je peux peut-être vous aider, s'il n'est pas encore trop tard..."
