L31_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "빌어먹을……!! 다시는 내 앞에서 그 얘기 꺼내지 말라고 했을……!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "バカ野郎……！！　俺の前で二度とその話をするなと言ったはず……！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Hey...!! I thought I told you to never bring that up ever ag...!!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "該死的……！不准再在我面前提起那件事……！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เฮ้ย...!! บอกแล้วไม่ใช่เหรอว่าอย่าฟื้นฝอยมันขึ้นมาอี...!!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Này...!! Tao tưởng đã nói với mày là đừng bao giờ kể lại việc đó nữa mà...!!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "可恶……！！我说过别在我面前提那件事……！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Verdammt noch mal ...! Ich habe dir doch gesagt, dass du diesen Namen vor mir nie wieder erwähnen sollst ...!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Nom d'un chien... ! Je t'ai pourtant déjà dit de ne plus jamais mentionner ce nom... !"
L30_1.m_Talk_FRA = L31_1
