L35_1 = "ALPHA_ACT1_PLOROGUE1@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3900101
L34_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "CHOWON_ALPHA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "어린 시절을 불우하게 보내셔서 대화 예절을 배울 기회가 없으셨나 보네요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "不遇な子ども時代を過ごされたせいで、\n会話のマナーが身についていないようですね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "It appears that you had a difficult childhood and did not have the opportunity to learn proper conversational etiquette."
L34_1.m_Talk_ENG = L35_1
L35_1 = "是小時候家裡沒大人，所以沒人教你什麼是禮貌嗎？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ท่าทางชีวิตวัยเด็กคุณจะลำบากเลยไม่ได้เรียนมารยาทในการสนทนาอย่างเหมาะสมมานะคะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Có vẻ như ngài đã có một thời thơ ấu khó khăn và không có cơ hội học cách xã giao cho thích hợp."
L34_1.m_Talk_VTN = L35_1
L35_1 = "看来你童年不幸，没能好好学会正确的会话礼仪呢。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wegen Ihrer schweren Kindheit, hatten Sie wohl keine Gelegenheit, Gesprächsknigge zu lernen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Vous avez dû vivre dans un environnement difficile ignorer ainsi les bonnes manières."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "ALPHA_ACT1_PLOROGUE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3900101
L35_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "CHOWON_ALPHA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "원하시면 지금 당장 성인용 예절 주입 코스를 마련해 드리죠."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "お望みでしたら、今すぐ大人向けのマナー叩き込みコースをご用意いたしましょう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "If you want, I could give you a quick lesson on proper manners."
L35_1.m_Talk_ENG = L36_1
L36_1 = "還是需要我現在就教你，跟人家對話的基本禮儀？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ถ้าสนใจ ฉันจะสอนมารยาทแบบด่วนๆ ให้ค่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nếu muốn, tôi có thể dạy một bài học ngắn về cách cư xử đúng mực."
L35_1.m_Talk_VTN = L36_1
L36_1 = "如果你愿意，我现在就可以为你准备成人版的礼节培养课程。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wenn Sie wollen, kann ich für Sie einen Kniggekurs für Erwachsene organisieren."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Si vous voulez, je peux mettre en place un programme d'enseignement des règles de savoir-vivre pour adultes."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
