L38_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "이, 이거 놔!! 너 내가 누군 줄 알아?!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "は、放せ！！　俺が誰だかわかってるのか！？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "L-let go of me! Do you even know who you’re dealing with, huh?!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "給我放開！！你知道我是誰嗎？！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ปะ-ปล่อยนะ! ไม่รู้รึไงว่าผมเป็นใครน่ะหา?!"
L37_1.m_Talk_THA = L38_1
L38_1 = "B-buông ra! Mày có biết mình đang gây chuyện với ai không hả?!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "放、放开我！！你知道我是谁吗？！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "L-lass los!! Weißt du überhaupt, wer ich bin?!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Lâche-moi ! Tu sais qui je suis, au moins ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT1_PLOROGUE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
