L38_1.m_Face = "UNIT_IDLE"
L38_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "초원 씨, 재혁 오라버니를 놔주세요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ナオさん、タツヤお兄様を放してください。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Chowon, please let go of Jaehyuk."
L38_1.m_Talk_ENG = L39_1
L39_1 = "初源，請你放開大哥。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โชวอน ปล่อยแจฮย็อกเถอะค่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Chowon, hãy buông Jaehyuk ra."
L38_1.m_Talk_VTN = L39_1
L39_1 = "桃沢梨绘，放开宰赫哥哥吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Chowon, lassen Sie Jaehyuk los."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Chowon, lâchez-le s'il vous plaît."
L38_1.m_Talk_FRA = L39_1
