L42_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "젠장, 빌어먹을 용병 나부랭이가!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ちくしょう、クソ傭兵の分際で！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "You filthy Mercenary! How dare you!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "該死的，你一個小小的傭兵！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไอ้ทหารรับจ้างเวรนี่! กล้าดียังไง!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Đồ lính đánh thuê bẩn thỉu! Sao mày dám!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "该死！可恶的臭佣兵！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Mensch, diese verflixte Söldnerin!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Enfer ! Qu'est-ce que c'est que cette idiote ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ALPHA_ACT1_PLOROGUE1@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900101
L42_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "지아 너, 직원 교육을 어떻게 한 거야? 저딴 짓을 하면 당장 잘라야지!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ユイ、お前のところの社員教育はどうなってるんだ？\nこんなことしたら即クビに決まってるだろ！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Jia, your dog has gone mad! Fire her this instance!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "沈佳，你是怎麼教育員工的？她這樣對我，你還不炒她魷魚？！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เจีย หมาเธอมันบ้าไปแล้วนะ! ไล่มันออกเดี๋ยวนี้เลย!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Jia, con chó của em phát điên rồi! Hãy sa thải cô ta đi!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "小佳，你是怎么管理职员的？竟然敢冒犯我，我要你立即解雇她！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Jia, wie hast du denn deine Mitarbeiter geschult? Bei so einem Verhalten musst du sie sofort kündigen!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Jia ! C'est comme ça que tu formes ton personnel ? Tu devrais virer tous ceux qui ont ce genre de comportement !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT1_PLOROGUE1@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3900101
L43_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "죄송해요, 오라버니. 제가 대신 사과드릴게요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ごめんなさい、お兄様。私が代わりにお詫びします。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I apologize on her behalf, Jaehyuk."
L43_1.m_Talk_ENG = L44_1
L44_1 = "大哥，抱歉，我代替她向你賠不是。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ต้องขออภัยแทนเธอด้วยนะคะแจฮย็อก"
L43_1.m_Talk_THA = L44_1
L44_1 = "Em thay mặt cô ấy xin lỗi anh, Jaehyuk."
L43_1.m_Talk_VTN = L44_1
L44_1 = "抱歉，哥哥。我替她向你道歉。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich entschuldige mich dafür, Jaehyuk."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Permettez-moi de vous présenter des excuses en son nom !"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ALPHA_ACT1_PLOROGUE1@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900101
L44_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "그보다 하실 말씀이라는 게……?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "それより、先ほどのお話とは……？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "But what was it you were trying to say...?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "不過大哥，你剛說的生意是……？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แต่เมื่อกี้คุณจะว่าอะไรนะคะ...?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nhưng anh đang cố nói gì thế...?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "不过刚才你要说的项目是……？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Was wolltest du mir nochmal erzählen ...?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Au fait, vous vouliez me dire quelque chose ?"
L44_1.m_Talk_FRA = L45_1
