L49_1 = "CUTSCENE_TALK_06"
L48_1.m_StartBGMFileName = L49_1
L48_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "네? 숙부님이 회장 권한대행에서 물러나신다고요?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "はい？　叔父様が会長代行から退くですって……？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Huh? Uncle is stepping down as acting President?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "什麼？叔叔要退出會長代理職務嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เอ๋? คุณลุงลงจากตำแหน่งรักษาการประธานแล้วเหรอคะ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Sao cơ? Bác sắp từ chức quyền Chủ Tịch ư?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "什么？叔父要卸任代理会长的职位？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Was? Mein Onkel tritt zurück?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Pardon ? Mon oncle va quitter ses fonctions de vice-président ?"
L48_1.m_Talk_FRA = L49_1
