L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3900101
L50_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
