L50_1.m_fWaitTime = 0
L51_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "그래. 실적 부진 때문에 다음 이사회 때 부회장 대신 새로운 회장을 세우려나 봐."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "ああ。業績不振という理由で、次回の理事会で\n副会長の代わりに新しい会長を立てるようだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Yeah. Due to his poor performance, the next board of directors seems to be trying to appoint someone new."
L50_1.m_Talk_ENG = L51_1
L51_1 = "對啊，因為集團經營不善，所以下次開董事會時，好像就會推選出新的會長。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ใช่ เพราะผลงานไม่ดีน่ะ คณะกรรมการชุดต่อไปกำลังพยายามจะแต่งตั้งคนใหม่อยู่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Đúng thế. Do hiệu quả kém, ban quản trị tiếp theo dường như đang cố gắng bổ nhiệm một người mới."
L50_1.m_Talk_VTN = L51_1
L51_1 = "是啊。好像是因为业绩不佳，要在下一次理事会推举新的会长取代他。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Genau. Aufgrund mangelnder Leistung will er bei der nächsten Vorstandsversammlung einen neuen Vorsitzenden wählen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "C'est exact. Je crois qu'à cause de ses mauvais résultats, ils veulent désigner un nouveau vice-président pour le prochain conseil d'administration."
L50_1.m_Talk_FRA = L51_1
