L2_1 = "ALPHA_ACT1_PLOROGUE1@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3900101
