L1_1.m_fWaitTime = 0
L2_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "우리같이 그 인간에게 밉보였던 사람들에게도 찬스가 왔다 이거지."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "彼に嫌われている我々にも、ついにチャンス到来ってことさ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "That means it’s our chance to get back at him."
L1_1.m_Talk_ENG = L2_1
L2_1 = "這對我們這些被他討厭的人而言，是個大好機會！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ซึ่งแปลว่าเป็นโอกาสที่เราจะกลับไปหาเขาแล้วนะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Điều đó có nghĩa là đây là cơ hội của chúng ta."
L1_1.m_Talk_VTN = L2_1
L2_1 = "意思就是像我们这样得罪过他的人，会有新的机会。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Dann haben wir, die bei ihm ganz schlecht im Kurs standen, auch eine Chance."
L1_1.m_Talk_DEU = L2_1
L2_1 = "C'est une occasion en or pour tous ceux qui le détestaient comme nous."
L1_1.m_Talk_FRA = L2_1
