L5_1 = "ALPHA_ACT1_PLOROGUE1@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3900101
L4_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "그래! 알파트릭스 그룹 전체를 손에 넣을 수 있는 찬스!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ああ！　アルファトリックスグループ全体を手に入れるチャンスだ！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Yeah! Our chance to seize control of the entire Alphatrix Group!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "是啊！可以把阿爾法崔克斯集團整碗捧走的大好機會！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ใช่! โอกาสที่เราจะยึดกลุ่มอัลฟาทริกซ์ทั้งกลุ่มไงล่ะ!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đúng thế! Cơ hội của chúng ta để chiếm quyền kiểm soát toàn bộ Tập Đoàn Alphatrix!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "对！将阿尔法崔克斯集团全部掌控在手中的机会！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Genau! Eine Chance, von der gesamten Alphatrix-Gruppe Besitz zu ergreifen!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais oui ! C'est l'occasion parfaite pour mettre la main sur le groupe Alphatrix !"
L4_1.m_Talk_FRA = L5_1
