L6_1 = "ALPHA_ACT1_PLOROGUE1@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3900101
L5_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L5_1.m_bWaitClick = true
