L5_1.m_Face = "UNIT_IDLE"
L5_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "그 이야기는 혹시 어디서 들으셨어요?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "その話はどこからお聞きになったのですか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Where did you hear this from?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "請問這件事是聽誰說的？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "คุณทราบเรื่องนี้มาจากไหนคะ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Anh đã nghe điều đó từ đâu vậy?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "你是从哪听说的这个消息？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wo hast du das gehört?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je pourrais savoir où vous avez entendu cette rumeur ?"
L5_1.m_Talk_FRA = L6_1
