L8_1 = "ALPHA_ACT1_PLOROGUE1@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3900101
L7_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "그야 당연히 날 밀어 주는 사람이지. 그리고 그게 뭐가 중요해?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "それは当然俺の後援者からさ。といっても、そんなことはどうでもいいだろう？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "From one of my backers, of course. But that’s not what’s important right now."
L7_1.m_Talk_ENG = L8_1
L8_1 = "當然是支持我的人囉！聽誰說的很重要嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ก็จากผู้สนับสนุนผมสักคนอยู่แล้ว แต่นั่นไม่สำคัญหรอกตอนนี้"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tất nhiên là từ một trong những người ủng hộ anh. Nhưng lúc này điều đó không quan trọng."
L7_1.m_Talk_VTN = L8_1
L8_1 = "当然是从背后支持我的人那里。这个不重要！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Natürlich bei dem, der mich unterstützt. Und was ist daran so wichtig?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "D'un de mes soutiens, bien entendu. Mais est-ce vraiment important ?"
L7_1.m_Talk_FRA = L8_1
