L11_1 = "ALPHA_ACT1_PLOROGUE1@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3900101
L10_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "어때, 지아야. 날 회장이 되게 도와 주는 건. 부회장 자리는 네게 줄 테니까."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "どうだ、ユイ。俺が会長になれるように手伝ってくれるなら、\n副会長の席を君にあげよう。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "So, what do you think, Jia? If you help me become President, I’ll give the Vice Chairman position to you."
L10_1.m_Talk_ENG = L11_1
L11_1 = "小佳，你怎麼說？只要你幫我坐上會長的位置，我就讓你做副會長！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ว่าไงล่ะเจีย? ถ้าช่วยให้ผมเป็นประธาน ผมจะให้เธอเป็นรองประธานนะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Thế em nghĩ sao, Jia? Nếu em giúp anh trở thành Chủ Tịch, anh sẽ để dành chức Phó Chủ Tịch cho em."
L10_1.m_Talk_VTN = L11_1
L11_1 = "怎么样，小佳。如果你帮助我成为会长，我可以将副会长的职位交给你。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wie wär‘s, Jia? Mich dabei zu unterstützen, Vorsitzender zu werden? Die Position als Vizepräsidentin überlasse ich dir."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Alors Jia, que dirais-tu de m'aider à accéder à la tête du groupe ? En échange, je te nommerai vice-présidente."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "ALPHA_ACT1_PLOROGUE1@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3900101
L11_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "지금처럼 계속 무시당하면서 살긴 싫잖아? 네 실력과 내 인망을 하나로 합치면……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "このまま無視され続けるのはイヤだろ？\n君の能力と俺の人望を合わせれば……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Aren’t you tired of being ignored in the family? But with your skills and my network working as one..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "像現在這樣被瞧不起，你不覺得很憋屈嗎？以你的能力再加上我的人脈……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เธอไม่เบื่อเหรอที่ใครๆ ในตระกูลก็ไม่สนใจน่ะ? ถ้าความสามารถของเธอมารวมกับการสร้างเครือข่ายของผมละก็..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Em không cảm thấy ấm ức vì bị gia đình bỏ rơi ư? Nhưng nếu kỹ năng của em và mạng lưới của anh kết hợp với nhau..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "你也不想像现在这样被别人边缘化吧？如果你的实力加上我的声望联合在一起……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du willst doch nicht für ewig so verachtet werden, oder? Wenn wir dein Können und mein Netzwerk an Leuten vereinen würden ..."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Tu n'en as pas assez d'être tout le temps méprisée ? En associant tes capacités à mon prestige, nous pourrions..."
L11_1.m_Talk_FRA = L12_1
