L15_1 = "ALPHA_ACT1_PLOROGUE1@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900101
L14_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L15_1 = "CECILIA_NPC_ALPHA_QM"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "쯧쯧. 오자마자 추한 꼴을 보는구나. 회사 일이 애들 장난도 아닐진데."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "やれやれ、到着早々こんな醜態を見せられるなんて。\n会社は子どものおままごとじゃないのに。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Tsk, tsk. Already scheming, are we? Remember, running a business isn’t child’s play."
L14_1.m_Talk_ENG = L15_1
L15_1 = "嘖嘖，瞧你這什麼樣子，公司的事又不是小孩子在辦家家酒。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ชิชะ นี่เราวางแผนกันแล้วใช่มั้ย? อย่าลืมสิ การทำธุรกิจไม่ใช่ของเด็กเล่นนะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Chậc chậc. Có kế hoạch cả rồi nhỉ? Hãy nhớ rằng, điều hành công ty không phải là trò trẻ con."
L14_1.m_Talk_VTN = L15_1
L15_1 = "啧啧。没想到刚到这里就看到你的丑态。生意上的事情可不是小孩子过家家。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Tss. Du zeigst dich schon direkt am Anfang von deiner schlechten Seite. Die Angelegenheiten des Unternehmens sind doch keine Kindersache."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Tss. Quelle scène gênante. La gestion d'une société, ce n'est pas pour les enfants."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "ALPHA_ACT1_PLOROGUE1@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3900101
L15_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "UNIT_LAUGH"
L15_1.m_Face = L16_1
L16_1 = "CECILIA_NPC_ALPHA_QM"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "m_Crash"
L15_1[L16_1] = 20
L16_1 = "하긴, 집안 돌아가는 꼴이 딱하니 젊은 것들에게도 기대할 것 없겠지만."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "まあ、一家全体が機能不全みたいなものだから、若い世代も期待薄だわね……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Well, looking at how the family’s been doing, I didn’t expect much from you youngsters, and you did not disappoint."
L15_1.m_Talk_ENG = L16_1
L16_1 = "不過也是啦，現在家道中落，對年輕一輩的也沒什麼好期待的。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แหม ดูบ้านนี้เข้าสิ ฉันไม่หวังอะไรจากพวกเด็กๆ นักหรอกนะ แล้วก็จะไม่ผิดหวังหรอก"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chà, nhìn cái cách làm việc của gia đình, tôi đã không kỳ vọng nhiều ở thế hệ trẻ các cô, và quả thực là không sai mà."
L15_1.m_Talk_VTN = L16_1
L16_1 = "不过，比对一下现在家族的样子，就不该对你们这些年轻人抱太大期望。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "In dieser Familie kann man von der jüngeren Generation auch nichts besseres erwarten."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Enfin vu l'état actuel de la famille, je ne m'attendais pas non plus à un miracle venant des plus jeunes."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
