L18_1 = "ALPHA_ACT1_PLOROGUE1@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3900101
L17_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "뭐야, 이 꼰대 흉내 내는 꼬맹이는?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "なんだ、この偉そうにしてるガキは？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Huh? Who does this little child think she is?!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "搞什麼，這個講話那麼老氣的小鬼是誰？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "หา? ยัยเด็กนี่คิดว่าตัวเองเป็นใครเนี่ย?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Hả? Đứa nhỏ này nghĩ nó là ai?!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "搞什么，这个装模作样的小不点是谁？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wer ist dieser kleine Kauz, der sich so herablassend benimmt?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Non mais elle se prend pour qui cette gamine ? Pour une boomer ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "ALPHA_ACT1_PLOROGUE1@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900101
L18_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_SURPRISE"
L19_1 = "CECILIA_NPC_ALPHA_QM"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "m_Bounce"
L20_1 = {}
L21_1 = 2
L22_1 = 0.15
L20_1[1] = L21_1
L20_1[2] = L22_1
L18_1[L19_1] = L20_1
L19_1 = "꼰대라고? 내가?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "偉そう？　私が？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Are you talking about me?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "你說我老氣？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "พูดถึงฉันเหรอ?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Cậu đang nói về tôi ư?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "装模作样？我？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Herablassend? Ich?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Moi, une boomer ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "ALPHA_ACT1_PLOROGUE1@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3900101
L19_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "UNIT_SERIOUS"
L19_1.m_Face = L20_1
L20_1 = "CECILIA_NPC_ALPHA_QM"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "못 배워 먹은 게 자랑이구나. 아버지가 이 꼴을 보셨으면 당장 호적에서 파 버렸을 게다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "礼儀知らずにもほどがあるわ。父がこのザマを見てたら、一族から即追放だったはずよ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "You wear your ignorance like a badge of honor. Father would be rolling in his grave if he saw what you were doing."
L19_1.m_Talk_ENG = L20_1
L20_1 = "沒大沒小的，爸爸要是看到你這副德性，一定會立刻把你除籍！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เธอนี่โง่ซะอย่างกับเป็นหน้าที่เลยนะ พ่อรู้ว่าเป็นยังไงคงดิ้นอยู่ในหลุมศพ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cậu đeo sự bất cẩn của mình lên cổ như một tấm huy chương ấy. Cha cậu chắc chắn sẽ rất sốc nếu ông ấy thấy những gì cậu đang làm."
L19_1.m_Talk_VTN = L20_1
L20_1 = "看来你真的是欠缺教养。如果父亲见到你这个样子，应该早就把你逐出家门了吧。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Schlechte Bildung ist nichts, womit man angeben sollte. Hätte Vater das gesehen, hätte er dich sofort aus dem Geburtenregister entfernt."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Tu ne devrais pas être aussi fier de ton manque de manières. Si ton père te voyait, il t'aurait sûrement déshérité."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
