L22_1 = "ALPHA_ACT1_PLOROGUE1@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3900101
L21_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "하……. 하다하다 이젠 별 미친 게 다……."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "はあ……こりゃ、気でも触れてんじゃないのか……？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Ugh... I don’t have time to deal with this..."
L21_1.m_Talk_ENG = L22_1
L22_1 = "什……這是哪來的瘋……"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อึก... ผมไม่มีเวลามาทำอะไรแบบนี้หรอกนะ..."
L21_1.m_Talk_THA = L22_1
L22_1 = "Ugh... Tao không có thời gian để dùng dằng với..."
L21_1.m_Talk_VTN = L22_1
L22_1 = "呃……到底是哪里冒出来的小屁孩……"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ha ... Was für ein Unsinn hier ..."
L21_1.m_Talk_DEU = L22_1
L22_1 = "C'est quoi cette tarée, encore..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "ALPHA_ACT1_PLOROGUE1@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3900101
L22_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "야, 김 비서! 이 꼬마 부모들 당장 데려 와! 어떤 연놈들인지 얼굴 좀 보게!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "おい、このガキの親を呼べ！　どんな面をしてるのか、この眼で確かめてやる！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Mr. Kim! Bring this child’s parents in front of me right now! I’ll show them who they’re messing with!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "金秘書！立刻把這小鬼的爸媽給我找來！我要問問他們是怎麼教小孩的！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "คุณคิม! ไปพาพ่อแม่เด็กนี่มาซิ! ผมจะให้รู้ซะหน่อยว่าเล่นอยู่กับใคร!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Thư kí Kim! Bảo cha mẹ con nhóc này đến trước mặt tôi ngay bây giờ! Tôi sẽ cho họ biết họ đang gây sự với ai!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "喂，金秘书！马上把这小孩的父母找来！我倒要看看是哪家的孩子！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Hey, Sekretär Kim! Bring mir sofort diese Eltern dieses Kindes! Ich will sehen, was das für Gestalten sind!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Hé le secrétaire ! Amène-moi ses parents tout de suite !"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "ALPHA_ACT1_PLOROGUE1@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3900101
L23_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "SECRETARY_NPC_ALPHA_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "도, 도련님……. 그게……."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ぼ、坊ちゃま……それが……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "S-sir... The thing is..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "少…少爺……那個……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ทะ-ท่านครับ... จริงๆ คือ..."
L23_1.m_Talk_THA = L24_1
L24_1 = "S-sếp... Vấn đề là..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "少、少爷……其实……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "H-Herr Vorsitzender ... Also das ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Monsieur... En fait..."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "ALPHA_ACT1_PLOROGUE1@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3900101
L24_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L25_1 = "CECILIA_NPC_ALPHA_QM"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "미안하다만 아버지는 진즉 돌아가셨느니라."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "悪いけど、父はとっくに亡くなっているわ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Sorry to tell you, but my father’s been dead for quite awhile now."
L24_1.m_Talk_ENG = L25_1
L25_1 = "不好意思喔，我爸早就死咧？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ขอโทษที่ต้องบอกนะ แต่พ่อฉันตายไปสักพักแล้วล่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Xin lỗi phải nói với cậu, nhưng cha tôi mất lâu rồi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "抱歉，我父亲早就过世了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Es tut mir leid, aber mein Vater ist schon längst verstorben."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Désolée, mais mon père est mort il y a bien longtemps."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "ALPHA_ACT1_PLOROGUE1@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3900101
L25_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "CECILIA_NPC_ALPHA_QM"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "그리고 내 어머니는 너희 일가 사람들이 푼돈 얼마 쥐어 줘서 바다 건너로 보내 버렸지."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そして母は、あなたの一族が小銭を握らせて海の向こうに追放してしまったの。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "As for my mother, your family sent her overseas with barely enough to rub two nickels together."
L25_1.m_Talk_ENG = L26_1
L26_1 = "而我媽媽也被你們一家人趕到海的另一邊！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ส่วนแม่นะเหรอ ตระกูลเธอก็ส่งไปต่างประเทศกับเศษเงินซะแล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Về phần mẹ tôi, gia đình cậu đã gửi bà ấy ra nước ngoài và để bà ấy sống vô cùng thiếu thốn."
L25_1.m_Talk_VTN = L26_1
L26_1 = "还有我母亲也很早就被你们家族用几个臭钱打发到了海外。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Und meine Mutter wurde von euch für einen Kleinbetrag hinters Meer verbannt."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Et en ce qui concerne ma mère, les tiens l'ont envoyée de l'autre côté de l'océan avec quelques sous en poche."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
