L29_1 = "ALPHA_ACT1_PLOROGUE1@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3900101
L28_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
