L28_1.m_fWaitTime = 0
L29_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "뭐? 그게 갑자기 뭔 헛소리야?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "はあ？　いきなり何の冗談だ？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Huh? What’s she even talking about?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "蛤？你在胡說八道什麼？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หา? ยัยเด็กนี่พูดอะไรของมัน?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Hả? Thậm chí tôi chẳng hiểu cô nhóc nói về chuyện gì nữa?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "什么？你突然胡说什么？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Was? Was redest du da für ein Schwachsinn?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Quoi ? Mais qu'est-ce que tu racontes ?"
L28_1.m_Talk_FRA = L29_1
