L30_1 = "ALPHA_ACT1_PLOROGUE1@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3900101
L29_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
