L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L30_1 = "CECILIA_NPC_ALPHA_QM"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "항렬로는 내가 네 녀석보다 위라는 게다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "一族の中では私が君より上の立場ということよ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I’m saying that I outrank you in the family."
L29_1.m_Talk_ENG = L30_1
L30_1 = "按照輩分，我可是在你之上！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันกำลังบอกว่าในตระกูลน่ะ ศักดิ์ฉันสูงกว่าเธอยังไงล่ะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi đang nói rằng tôi có thứ bậc cao hơn cậu trong gia đình."
L29_1.m_Talk_VTN = L30_1
L30_1 = "如果以辈分来说，我可是你这家伙的长辈。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Das bedeutet so viel wie, dass ich über dir in der Rangfolge stehe."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Sur le degré familial, j'occupe une position supérieure à la tienne."
L29_1.m_Talk_FRA = L30_1
