L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "m_Crash"
L30_1[L31_1] = 20
L31_1 = "집안 어르신에게는 존대를 써야지, 신재혁?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "序列がわかったのなら口を慎まなくっちゃね、タツヤ？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Now, how about showing some respect to your elders, hmm? Shin Jaehyuk?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "對家裡的長輩要有禮貌，沈赫！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไหน เคารพผู้หลักผู้ใหญ่หน่อยดีมั้ย? ชิน แจฮย็อก?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Vậy bây giờ phải làm gì để thể hiện sự tôn trọng trưởng bối nào, hmm? Hả Shin Jaehyuk?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "难道你不该对家族的长辈抱有尊敬吗，沈宰赫？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Zu den Familienältesten muss du doch höflich sein, Jaehyuk?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Allons Shin Jaehyuk, est-ce bien une façon de t'adresser à ton aïeule ?"
L30_1.m_Talk_FRA = L31_1
