L34_1 = "ALPHA_ACT1_PLOROGUE1@233#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3900101
L33_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "HEAVYARMSCEO_NPC_ALPHA_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "김 비서! 저 꼬마가 한 얘기는 다 뭐야!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "おい、あのガキはいったい何をほざいているんだ？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Mr. Kim! What’s this kid talking about?!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "金秘書！那小鬼在說什麼我怎麼都聽不懂？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คุณคิม! ยัยเด็กนี่มันพูดเรื่องอะไรเนี่ย!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Thư kí Kim! Đứa nhóc này đang nói gì thế?!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "金秘书！这小孩说的是什么意思？！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Sekretär Kim! Was hat es mit diesem Geschwafel dieses Kindes auf sich?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hé ! Kim ! Tu peux me dire ce qui se passe ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "ALPHA_ACT1_PLOROGUE1@234#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3900101
L34_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "SECRETARY_NPC_ALPHA_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "그게……. 죄송하지만 사실입니다, 도련님. 생체 인증까지 마치셔서 저희로선 도저히……."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それが……申しあげにくいのですが、事実です。\n生体認証まで済ませているので、私たちとしてはどうすることも……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I’m sorry to inform you, but it’s all true sir. Her biometrics were already verified, so there was nothing we could do..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "那個……很抱歉，她說的是事實沒錯。我們有確認過她的身分，確實……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ขออภัยที่ต้องบอกอย่างนี้ ทั้งหมดเป็นความจริงครับ ยืนยันข้อมูลชีวมาตรของเธอแล้ว เราคงทำอะไรไม่ได้..."
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi rất tiếc phải thông báo cho ngài, nhưng tất cả đều là sự thật cả. Sinh trắc học của cô ấy đã được xác minh, vậy nên chúng ta chẳng thể làm gì..."
L34_1.m_Talk_VTN = L35_1
L35_1 = "少爷……虽然很抱歉，但她说的都是事实。而且已经经过了生物识别认证，所以我们也无能为力……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Das ist ... So leid es mir auch tut, die Wahrheit. Sogar die biometrische Authentifizierung bestätigt dies ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Désolé, mais c'est a vérité. Ses propos ont été confirmés par authentification biométrique, on ne peut rien y faire..."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
