L38_1 = "ALPHA_ACT1_PLOROGUE1@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900101
L37_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_IDLE"
L38_1 = "CECILIA_NPC_ALPHA_QM"
L37_1.m_CharStrID = L38_1
L38_1 = "R_M_I"
L37_1.m_Pos = L38_1
L38_1 = "만나서 반갑구나, 지아야. 아버지에게 얘기 많이 들었느니라."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "会えて嬉しいわ、ユイちゃん。父から話は色々聞いているわよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Nice to see you, Jia. I heard a lot about you from Father."
L37_1.m_Talk_ENG = L38_1
L38_1 = "小佳，你好啊，我常聽爸爸提起你呢～"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ยินดีที่ได้พบนะเจีย พ่อฉันเล่าเรื่องเธอให้ฟังเยอะแยะเลย"
L37_1.m_Talk_THA = L38_1
L38_1 = "Rất vui được gặp cháu, Jia. Cô đã nghe Cha nói rất nhiều về cháu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "见到你很高兴，小佳。我听父亲提过你很多次。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Freut mich, dich zu sehen, Jia. Ich habe viel von Vater gehört."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ravie de te rencontrer, Jia. Ton père m'a beaucoup parlé de toi."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT1_PLOROGUE1@238#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 238
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900101
L38_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "CECILIA_NPC_ALPHA_QM"
L38_1.m_CharStrID = L39_1
L39_1 = "R"
L38_1.m_Pos = L39_1
L39_1 = "네가 그리도 영특하다지. 못난 것들 상대해 주느라 고생이 이만저만 아니었겠구나."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "君はとても聡明だとか。\nこれまでバカな連中を相手にするのにさぞ大変だったでしょうね。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "He told me how brilliant you are. I’m sure you get headaches from dealing with these fools all day long."
L38_1.m_Talk_ENG = L39_1
L39_1 = "爸爸常誇你聰明，要面對這些沒用的傢伙，應該很辛苦吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เขาเล่าให้ฉันฟังแล้วล่ะว่าเธอฉลาดขนาดไหน ฉันว่าเธอต้องดีลกับพวกโง่นี่ทั้งวันคงปวดหัวแย่"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ông ấy nói với cô rằng cháu rất thông minh. Cô chắc là cháu phải đau đầu khi cứ phải đối phó với những kẻ ngốc này suốt ngày."
L38_1.m_Talk_VTN = L39_1
L39_1 = "说你非常聪明。每天要和这些蠢货打交道，应该很辛苦吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Man sagt dir deine Intelligenz nach. Muss bestimmt schwer sein, dich mit niveaulosen Menschen abgeben zu müssen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Il m'a dit que tu étais une jeune fille très perspicace. Ça ne doit pas être facile de tenir compagnie à ces imbéciles."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ALPHA_ACT1_PLOROGUE1@239#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900101
L39_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L40_1 = "L"
L39_1.m_Pos = L40_1
L40_1 = "영특하다는 칭찬은 할아버님 말고는 들은 적이 없었는데……."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "聡明だと誉めてくださったのは、お祖父様だけでしたが……"
L39_1.m_Talk_JPN = L40_1
L40_1 = "The only person to say I say brilliant was Grandfather..."
L39_1.m_Talk_ENG = L40_1
L40_1 = "只有爺爺會稱讚我聰明……"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คนที่บอกว่าฉันฉลาดมีแต่คุณปู่นะคะ..."
L39_1.m_Talk_THA = L40_1
L40_1 = "Người duy nhất nói rằng tôi thông minh là Ông nội..."
L39_1.m_Talk_VTN = L40_1
L40_1 = "会夸我聪明的除了爷爷以外，应该没有别人吧……"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Dass ich intelligent sei, höre ich seit Großvater zum ersten Mal ..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Perspicace ? C'est ce que mon grand-père me disait toujours..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "ALPHA_ACT1_PLOROGUE1@240#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 240
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3900101
