L40_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L41_1 = "L"
L40_1.m_Pos = L41_1
L41_1 = "혹시 그 아버지라는 분이…… 저희 할아버님인가요?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "まさかそのお父様という方は……私のお祖父様なのでしょうか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Is your father... my Grandfather?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "請問你說的爸爸……就是我們的爺爺嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "พ่อคุณ... คือคุณปู่ฉันเหรอคะ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cha cô... có phải là Ông nội tôi không?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你说的父亲……难道是我的爷爷？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ist Ihr Vater etwa ... mein Großvater?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Mais alors, votre père serait mon..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
