L41_1[L42_1] = L43_1
L42_1 = "옳지. 잘 알아 봤다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "さすがお察しがよいこと。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "There you go. Good job putting the pieces together."
L41_1.m_Talk_ENG = L42_1
L42_1 = "正確，真聰明。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "นั่นไงล่ะ แก็ตแพ็ตเชื่อมโยงเป็นเลิศ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Đúng rồi đấy. Cháu quả là rất giỏi xâu chuỗi mọi thứ."
L41_1.m_Talk_VTN = L42_1
L42_1 = "很好，你猜得没错。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Richtig. Das hast du gut erkannt."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Bien joué. Tu as tout compris."
L41_1.m_Talk_FRA = L42_1
