L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_IDLE"
L44_1 = "CECILIA_NPC_ALPHA_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "기억해 두거라, 지아야. 내 이름은 <color=#ffd34c>세실리아</color>."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "憶えておきなさい、ユイちゃん。私の名前は<color=#ffd34c>セシリア</color>。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Jia, keep in mind who I am. My name is <color=#ffd34c>Cecilia</color>."
L43_1.m_Talk_ENG = L44_1
L44_1 = "小佳，你要記好喔，我叫<color=#ffd34c>賽希莉亞</color>。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เจีย จำไว้ให้ดีนะว่าฉันเป็นใคร ฉันชื่อ<color=#ffd34c>เซซิเลีย</color>"
L43_1.m_Talk_THA = L44_1
L44_1 = "Jia, hãy nhớ tên cô nhé. Tên cô là <color=#ffd34c>Cecilia</color>."
L43_1.m_Talk_VTN = L44_1
L44_1 = "记好了，小佳。我的名字叫<color=#ffd34c>赛西莉亚</color>。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Merke dir, dass mein Name <color=#ffd34c>Cecilia</color> lautet."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je m'appelle <color=#ffd34c>Cecilia</color>, retiens bien ce nom."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ALPHA_ACT1_PLOROGUE1@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900101
L44_1.m_CutScenStrID = "ALPHA_ACT1_PLOROGUE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "CECILIA_NPC_ALPHA_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "아버지가 돌아가시자마자 둘째 부인이란 이유로 억울하게 쫓겨난 캐서린의 딸이자……."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "父が他界してすぐ、側妻だったなんて理由で無念にも締め出されたキャサリンの娘であり……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I am the daughter of Father’s second wife, Catherine, who was forced into exile when Father passed away."
L44_1.m_Talk_ENG = L45_1
L45_1 = "爸爸過世時，二房 凱瑟琳遭逐出家門，而我就是他們的女兒……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฉันเป็นลูกสาวแคเทอรีน ภรรยาคนที่สองของคุณพ่อ ที่ถูกบังคับให้ออกจากตระกูลไปตอนคุณพ่อเสียน่ะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô là con gái của người thiếp thứ hai của Cha, Catherine, người đã bị buộc phải đi đày khi Cha qua đời."
L44_1.m_Talk_VTN = L45_1
L45_1 = "是父亲过世之后，被流放的二夫人凯瑟琳的女儿……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich bin die Tochter von Catherine, die, nur weil sie die zweite Frau war, ausgeschlossen wurde, direkt als Vater verstorben war."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je suis la fille de Catherine, celle qui a été chassée à la mort de son mari juste parce qu'elle était sa seconde épouse."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
