L46_1 = "장차, 알파트릭스 그룹을 씹어 삼킬 이름일 테니!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "この先、アルファトリックスグループを掌握する存在なのだ！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Remember my name, for I will be the successor to the Alphatrix Group!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "我會將整個阿爾法崔克斯集團奪回來！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "จำชื่อฉันไว้นะ เพราะฉันจะเป็นผู้สืบทอดของกลุ่มอัลฟาทริกซ์!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Hãy nhớ tên cô, vì cô sẽ là người thừa kế Tập Đoàn Alphatrix!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "是未来要打垮阿尔法崔克斯集团的人！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "In Zukunft werde ich nämlich die Alphatrix-Gruppe an mich reißen!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Ce nom, c'est celui qui s'emparera du groupe Alphatrix !"
L45_1.m_Talk_FRA = L46_1
